"use client";
import React, { useState, useEffect } from 'react';
import Sidebar from '@/components/Sidebar';
import ChatInterface from '@/components/ChatInterface';
import AvatarView from '@/components/AvatarView';
import dynamic from 'next/dynamic';
import ActionPanel from '@/components/ActionPanel';

const Live2DView = dynamic(() => import('@/components/Live2DView'), { ssr: false });
import ActionIssuesPanel from '@/components/ActionIssuesPanel';
import MemoryExplorer from '@/components/MemoryExplorer';
import LivestreamDashboard from '@/components/LivestreamDashboard';
import ProfileEditor from '@/components/ProfileEditor';
import SettingsPanel from '@/components/SettingsPanel';
import StatsPanel from '@/components/StatsPanel';
import DrawLab from '@/components/DrawLab';
import GamePanel from '@/components/GamePanel';
import VideoPanel from '@/components/VideoPanel';
import IdentityPanel from '@/components/IdentityPanel';
import { Menu, X } from 'lucide-react';

export default function Home() {
  const [activeTab, setActiveTab] = useState('chat');
  const [isTalking, setIsTalking] = useState(false);
  const [emotion, setEmotion] = useState("neutral");
  const [agentState, setAgentState] = useState("");
  const [isThinking, setIsThinking] = useState(false);
  const [gesture, setGesture] = useState("");
  const [gestureTick, setGestureTick] = useState(0);
  const [audioVolume, setAudioVolume] = useState(0);
  const [agentMode, setAgentMode] = useState('normal'); // 'normal' | 'stream' | 'dev'
  const [avatarRenderer, setAvatarRenderer] = useState<'vrm' | 'live2d'>('vrm');
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Load mode from localStorage on mount
  useEffect(() => {
    const savedMode = localStorage.getItem('agent_mode');
    if (savedMode) setAgentMode(savedMode);
    const savedRenderer = localStorage.getItem('avatar_renderer') as 'vrm' | 'live2d' | null;
    if (savedRenderer) setAvatarRenderer(savedRenderer);
  }, []);

  // Save mode when changed
  const handleModeChange = (mode: string) => {
    setAgentMode(mode);
    localStorage.setItem('agent_mode', mode);
  };

  const handleRendererChange = (renderer: 'vrm' | 'live2d') => {
    setAvatarRenderer(renderer);
    localStorage.setItem('avatar_renderer', renderer);
  };

  // Close mobile menu when tab changes
  const handleTabChange = (tab: string) => {
    setActiveTab(tab);
    setMobileMenuOpen(false);
  };

  return (
    <main className="flex h-dvh w-full overflow-hidden bg-[#0f0f12] text-white">
      {/* Mobile Menu Button */}
      <button
        className="md:hidden fixed top-3 left-3 z-50 p-2 rounded-xl glass"
        onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
      >
        {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
      </button>

      {/* 1. Sidebar - Desktop: always visible, Mobile: overlay */}
      <div className="hidden md:block">
        <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />
      </div>

      {/* Mobile Sidebar Overlay */}
      {mobileMenuOpen && (
        <div className="md:hidden fixed inset-0 z-40">
          <div className="absolute inset-0 bg-black/60" onClick={() => setMobileMenuOpen(false)} />
          <div className="absolute left-0 top-0 h-full z-50">
            <Sidebar activeTab={activeTab} setActiveTab={handleTabChange} />
          </div>
        </div>
      )}

      {/* 2. Main Content Area */}
      <div className="flex-1 flex max-w-full relative">

        {/* Avatar Panel (Right Side by default or Split) */}
        {/* Let's do a split view: Left Chat, Right Avatar */}

        <div className="flex-1 flex flex-col h-full relative z-10 p-2 md:p-4">
          {/* Tab Content Routing */}
          {activeTab === 'chat' && (
            <div className="flex h-full gap-2 md:gap-4">
              {/* Chat Column (Full width on mobile, 1/3 on XL) */}
              <div className="w-full xl:w-1/3 h-full flex flex-col gap-2">
                {agentMode === 'stream' ? (
                  <>
                    <div className="hidden xl:block h-[18%] min-h-[110px] rounded-3xl overflow-hidden glass-panel">
                      <LivestreamDashboard threadId="default_thread" />
                    </div>
                    <div className="h-[24%] min-h-[120px] rounded-3xl overflow-hidden glass-panel">
                      <ActionPanel threadId="default_thread" />
                    </div>
                  </>
                ) : (
                  <div className="hidden md:block h-[24%] min-h-[120px] rounded-3xl overflow-hidden glass-panel">
                    <ActionPanel threadId="default_thread" />
                  </div>
                )}
                <div className="flex-1 min-h-0 glass rounded-2xl md:rounded-3xl overflow-hidden relative">
                  {/* Background Effect */}
                  <div className="absolute top-0 w-full h-32 bg-gradient-to-b from-blue-900/20 to-transparent pointer-events-none" />
                  <ChatInterface
                    onStateChange={(talking, emo, thinking) => {
                      setIsTalking(talking);
                      setEmotion(emo);
                      if (typeof thinking === "boolean") {
                        setIsThinking(thinking);
                      }
                    }}
                    onAgentStateChange={(state) => setAgentState(state)}
                    onGestureChange={(g) => {
                      setGesture(g);
                      setGestureTick((v) => v + 1);
                    }}
                    onVolumeChange={(v) => setAudioVolume(v)}
                    agentMode={agentMode} // Pass mode to chat
                  />
                </div>
              </div>

              {/* Avatar Panel (Right, Grows to fill space) */}
              <div className="hidden xl:flex flex-1 h-full min-h-0 flex-col gap-2">
                <div className="flex-1 min-h-0 rounded-3xl overflow-hidden glass-panel">
                  {avatarRenderer === 'live2d' ? (
                    <Live2DView
                      isTalking={isTalking}
                      emotion={emotion}
                      isThinking={isThinking}
                      stateTag={agentState}
                      gesture={gesture}
                      gestureTick={gestureTick}
                      audioVolume={audioVolume}
                    />
                  ) : (
                    <AvatarView
                      isTalking={isTalking}
                      emotion={emotion}
                      isThinking={isThinking}
                      stateTag={agentState}
                      gesture={gesture}
                      gestureTick={gestureTick}
                      audioVolume={audioVolume}
                    />
                  )}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'memories' && (
            <div className="flex-1 glass rounded-2xl md:rounded-3xl p-4 md:p-8 overflow-y-auto">
              <MemoryExplorer />
            </div>
          )}

          {activeTab === 'profile' && (
            <div className="flex-1 glass rounded-2xl md:rounded-3xl p-4 md:p-8 overflow-y-auto">
              <ProfileEditor />
            </div>
          )}

          {activeTab === 'settings' && (
            <div className="flex-1 glass rounded-2xl md:rounded-3xl p-4 md:p-8 overflow-y-auto">
              <SettingsPanel
                currentMode={agentMode}
                onModeChange={handleModeChange}
                avatarRenderer={avatarRenderer}
                onRendererChange={handleRendererChange}
              />
            </div>
          )}

          {activeTab === 'stats' && (
            <div className="flex-1 glass rounded-3xl overflow-hidden">
              <StatsPanel />
            </div>
          )}

          {activeTab === 'action_issues' && (
            <div className="flex-1 glass rounded-3xl overflow-hidden">
              <ActionIssuesPanel threadId="default_thread" />
            </div>
          )}

          {activeTab === 'draw_lab' && (
            <div className="flex-1 glass rounded-3xl overflow-hidden">
              <DrawLab />
            </div>
          )}

          {activeTab === 'game' && (
            <div className="flex-1 glass rounded-3xl overflow-hidden">
              <GamePanel />
            </div>
          )}

          {activeTab === 'video' && (
            <div className="flex-1 glass rounded-3xl overflow-hidden">
              <VideoPanel />
            </div>
          )}

          {activeTab === 'identity' && (
            <div className="flex-1 glass rounded-3xl overflow-hidden">
              <IdentityPanel />
            </div>
          )}

          {activeTab !== 'chat' && activeTab !== 'memories' && activeTab !== 'profile' && activeTab !== 'settings' && activeTab !== 'stats' && activeTab !== 'action_issues' && activeTab !== 'draw_lab' && activeTab !== 'game' && activeTab !== 'video' && activeTab !== 'identity' && (
            <div className="flex-1 glass rounded-2xl md:rounded-3xl p-4 md:p-8 flex items-center justify-center">
              <div className="text-center">
                <h2 className="text-3xl font-bold mb-2">準備中</h2>
                <p className="text-gray-500">{activeTab} モジュールは現在開発中です。</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </main>
  );
}

"use client";
import React, { useEffect, useState } from "react";
import { AlertTriangle, RefreshCw } from "lucide-react";
import { apiClient } from "@/lib/apiClient";

type LegacyPendingIssue = {
  id?: string;
  action_type?: string;
  status?: string;
  reason?: string;
  message_id?: string;
  created_at?: number;
  updated_at?: number;
};

interface ActionIssuesPanelProps {
  threadId?: string;
}

const statusLabel = (status?: string) => {
  switch ((status || "").toUpperCase()) {
    case "REJECTED":
      return "却下";
    case "ERROR":
      return "失敗";
    case "ARCHIVED":
      return "アーカイブ";
    default:
      return status || "不明";
  }
};

export default function ActionIssuesPanel({ threadId = "default_thread" }: ActionIssuesPanelProps) {
  const [items, setItems] = useState<LegacyPendingIssue[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
  const [showArchived, setShowArchived] = useState(false);

  const fetchIssues = async () => {
    setLoading(true);
    setError(null);
    try {
      const statusParam = showArchived ? "ERROR,REJECTED,ARCHIVED" : "ERROR,REJECTED";
      const data = await apiClient.fetchActionIssues(threadId, statusParam, 100);
      setItems(Array.isArray(data?.items) ? data.items as LegacyPendingIssue[] : []);
    } catch (e) {
      console.error(e);
      setError("失敗/却下の取得に失敗しました");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchIssues();
  }, [threadId, showArchived]);

  const deleteIssue = async (id?: string) => {
    if (!id) return;
    const ok = window.confirm("この失敗/却下アクションを削除しますか？");
    if (!ok) return;
    setPendingDeleteId(id);
    try {
      await apiClient.archiveAction(id);
      setItems((prev) => prev.filter((item) => item.id !== id));
    } catch (e) {
      console.error(e);
      setError("削除に失敗しました");
    } finally {
      setPendingDeleteId(null);
    }
  };

  return (
    <div className="h-full w-full p-4 md:p-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 text-sm font-semibold text-white/90">
          <AlertTriangle size={16} className="text-rose-300" />
          失敗/却下アクション
        </div>
        <div className="flex items-center gap-3">
          <label className="flex items-center gap-2 text-[11px] text-gray-300">
            <input
              type="checkbox"
              checked={showArchived}
              onChange={(e) => setShowArchived(e.target.checked)}
              className="h-3 w-3 accent-rose-400"
            />
            アーカイブも表示
          </label>
          <button
            onClick={fetchIssues}
            className="flex items-center gap-1 text-xs text-gray-300 hover:text-white"
            title="再読み込み"
          >
            <RefreshCw size={14} />
            更新
          </button>
        </div>
      </div>

      <div className="mt-1 text-[11px] text-gray-400">件数: {items.length}</div>
      {error && <div className="mt-2 text-xs text-red-300">{error}</div>}

      <div className="mt-4 space-y-3">
        {items.map((item) => (
          <div key={item.id} className="rounded-xl border border-rose-500/30 bg-rose-900/20 p-3">
            <div className="flex items-center justify-between text-xs text-rose-100">
              <span className="flex items-center gap-1">
                <AlertTriangle size={12} />
                {statusLabel(item.status)}
              </span>
              <span className="text-rose-200/80">{item.action_type || item.id}</span>
            </div>
            <div className="mt-1 text-[11px] text-rose-100/90">理由: {item.reason || "理由なし"}</div>
            {item.created_at && (
              <div className="mt-1 text-[10px] text-rose-200/70">
                登録: {new Date(item.created_at * 1000).toLocaleString()}
              </div>
            )}
            <div className="mt-2">
              <button
                onClick={() => deleteIssue(item.id)}
                disabled={pendingDeleteId === item.id}
                className="rounded-md border border-rose-400/40 bg-rose-500/20 px-2 py-1 text-[10px] text-rose-100 hover:bg-rose-500/30 disabled:opacity-60"
              >
                削除
              </button>
            </div>
          </div>
        ))}
        {!loading && items.length === 0 && (
          <div className="text-xs text-gray-400">失敗・却下の履歴はありません。</div>
        )}
        {loading && (
          <div className="text-xs text-gray-400">読み込み中…</div>
        )}
      </div>
    </div>
  );
}

"use client";
import React, { useEffect, useMemo, useState, startTransition } from "react";
import { apiClient } from "@/lib/apiClient";
import { Check, X, RefreshCw } from "lucide-react";
import type { PendingAction, ActionResult } from "@/lib/types";

type Phase5Pending = PendingAction;
type Phase5Result = ActionResult;

interface ActionPanelProps {
  threadId?: string;
}

const riskBadge = (risk?: string) => {
  const key = (risk || "").toUpperCase();
  switch (key) {
    case "SAFE":
      return "border-emerald-400/30 text-emerald-200 bg-emerald-900/20";
    case "LOW":
      return "border-sky-400/30 text-sky-200 bg-sky-900/20";
    case "MEDIUM":
    case "MED":
      return "border-amber-400/30 text-amber-200 bg-amber-900/20";
    case "HIGH":
      return "border-orange-400/30 text-orange-200 bg-orange-900/20";
    case "CRITICAL":
      return "border-red-400/40 text-red-200 bg-red-900/30";
    default:
      return "border-white/10 text-gray-300 bg-white/5";
  }
};

type TweetProposal = {
  tweet_text: string;
  proposed_at: number;
  id: string;
  thread_id: string;
};

export default function ActionPanel({ threadId = "default_thread" }: ActionPanelProps) {
  const [pending, setPending] = useState<Phase5Pending[]>([]);
  const [reviewToken, setReviewToken] = useState<string | null>(null);
  const [results, setResults] = useState<Phase5Result[]>([]);
  const [historyResults, setHistoryResults] = useState<Phase5Result[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reasonById, setReasonById] = useState<Record<string, string>>({});
  const [resultTab, setResultTab] = useState<"state" | "history">("state");
  const [tweetProposal, setTweetProposal] = useState<TweetProposal | null>(null);

  const fetchPending = async () => {
    try {
      const data = await apiClient.fetchPhase5Pending(threadId);
      const token = typeof data?.review_token === "string" ? data.review_token : null;
      setReviewToken(token);
      const items = (Array.isArray(data?.items) ? data.items : []) as Phase5Pending[];
      const normalized = items.map((item: Phase5Pending) => {
        if ((item?.kind || "").toLowerCase() === "say") {
          return { ...item, review_token: item.review_token || token || undefined };
        }
        return item;
      });
      setPending(normalized);
    } catch (e) {
      console.error(e);
      setError("pending_actions の取得に失敗しました");
    }
  };

  const fetchResults = async () => {
    try {
      const data = await apiClient.fetchPhase5Results(threadId);
      setResults((Array.isArray(data?.items) ? data.items : []) as Phase5Result[]);
    } catch (e) {
      console.error(e);
      setError("action_results の取得に失敗しました");
    }
  };

  const fetchHistoryResults = async () => {
    try {
      const data = await apiClient.fetchPhase5ResultsHistory(threadId, 50);
      setHistoryResults((Array.isArray(data?.items) ? data.items : []) as Phase5Result[]);
    } catch (e) {
      console.error(e);
      setError("action_results 履歴の取得に失敗しました");
    }
  };

  const refreshAll = async () => {
    setLoading(true);
    setError(null);
    await Promise.all([fetchPending(), fetchResults(), fetchHistoryResults()]);
    setLoading(false);
  };

  useEffect(() => {
    startTransition(() => { refreshAll(); });
  }, [threadId]);

  // Poll for autonomous tweet proposals (from Reflection Engine)
  useEffect(() => {
    const pollTweet = async () => {
      try {
        const data = await apiClient.fetchPendingTweet();
        setTweetProposal(data?.proposal ?? null);
      } catch {
        // Silently ignore polling errors
      }
    };
    pollTweet();
    const interval = setInterval(pollTweet, 30_000);
    return () => clearInterval(interval);
  }, []);

  const handleTweetDecision = async (decision: "approve" | "reject") => {
    try {
      if (decision === "approve" && tweetProposal) {
        await apiClient.approveTweet(tweetProposal.tweet_text, tweetProposal.thread_id || threadId);
      } else {
        await apiClient.rejectTweet();
      }
      setTweetProposal(null);
    } catch (e) {
      console.error(e);
      setError(`ツイートの${decision}に失敗しました`);
    }
  };

  useEffect(() => {
    const handler = (ev: Event) => {
      const detail = (ev as CustomEvent).detail || {};
      if (!detail?.name) return;
      // action_proposed / action_approved / action_blocked
      refreshAll();
    };
    if (typeof window !== "undefined") {
      window.addEventListener("phase5-action-event", handler as EventListener);
      return () => window.removeEventListener("phase5-action-event", handler as EventListener);
    }
  }, []);

  const updateReason = (pendingId: string | undefined, value: string) => {
    if (!pendingId) return;
    setReasonById((prev) => ({ ...prev, [pendingId]: value }));
  };

  const postDecision = async (item: Phase5Pending, decision: "approve" | "reject") => {
    const kind = (item.kind || "").toLowerCase();
    try {
      if (kind === "say") {
        const token = item.review_token || reviewToken;
        if (!token) {
          setError("review_token が見つからないため、承認/拒否できません");
          return;
        }
        await apiClient.postReviewDecision(decision, threadId, token);
      } else {
        const actionId = item.action_id;
        const pendingId = item.pending_id;
        if (!actionId || !pendingId) {
          setError("action_id または pending_id が不足しているため、承認/拒否できません");
          return;
        }
        const reason = reasonById[pendingId] || "";
        await apiClient.postPhase5Decision(actionId, decision, {
          thread_id: threadId,
          pending_id: pendingId,
          reason,
        });
      }
      await refreshAll();
    } catch (e) {
      console.error(e);
      setError(`アクションの${decision}に失敗しました`);
    }
  };

  const pendingCount = pending.length;
  const hasPending = pendingCount > 0;
  const recentResults = useMemo(() => results.slice(-6).reverse(), [results]);
  const recentHistoryResults = useMemo(() => historyResults.slice(0, 10), [historyResults]);

  return (
    <div className="h-full w-full p-2.5 text-[13px] flex flex-col min-h-0">
      <div className="flex items-center justify-between">
        <div className="text-sm font-semibold text-white/90">Phase5 Actions</div>
        <button
          onClick={refreshAll}
          className="flex items-center gap-1 text-xs text-gray-300 hover:text-white"
          title="再読み込み"
        >
          <RefreshCw size={14} />
          更新
        </button>
      </div>
      <div className="mt-0.5 text-[11px] text-gray-400">pending: {pendingCount}</div>
      {error && <div className="mt-1 text-xs text-red-300">{error}</div>}

      <div
        className={`mt-2.5 space-y-2.5 pr-1 ${
          hasPending || tweetProposal ? "flex-1 min-h-0 overflow-y-auto" : ""
        }`}
      >
        {/* Autonomous tweet proposal (from Reflection Engine) */}
        {tweetProposal && (
          <div className="rounded-xl border border-blue-400/30 bg-blue-900/20 p-2.5">
            <div className="flex items-center justify-between gap-2">
              <div className="text-sm text-blue-100 flex items-center gap-1.5">
                <span className="text-base">𝕏</span> Tweet Proposal
              </div>
              <span className="text-[10px] px-2 py-0.5 rounded-full border border-blue-400/30 text-blue-200 bg-blue-900/30">
                {tweetProposal.tweet_text.length}/280
              </span>
            </div>
            <div className="mt-2 text-xs text-gray-200 bg-black/30 rounded-lg p-2 whitespace-pre-wrap">
              {tweetProposal.tweet_text}
            </div>
            <div className="mt-1.5 flex items-center gap-2">
              <button
                onClick={() => handleTweetDecision("approve")}
                className="flex items-center gap-1 rounded-lg border border-emerald-500/40 bg-emerald-500/20 px-2 py-1 text-xs text-emerald-100"
              >
                <Check size={12} /> 投稿する
              </button>
              <button
                onClick={() => handleTweetDecision("reject")}
                className="flex items-center gap-1 rounded-lg border border-red-500/40 bg-red-500/20 px-2 py-1 text-xs text-red-100"
              >
                <X size={12} /> 却下
              </button>
            </div>
          </div>
        )}
        {pending.map((item, idx) => {
          const pendingId = item.pending_id;
          const actionId = item.action_id;
          const decision = item.decision || {};
          const isSayPreview = (item.kind || "").toLowerCase() === "say";
          const isTweetPreview = actionId === "post_tweet";
          const title = isSayPreview ? "Speech Preview" : isTweetPreview ? "Tweet Preview" : item.name || actionId;
          const risk = item.risk_level || item.risk;
          const itemKey =
            pendingId ||
            `${actionId || item.kind || "unknown-action"}:${item.requested_at || "no-ts"}:${item.name || "no-name"}:${idx}`;
          return (
            <div key={itemKey} className="rounded-xl border border-white/10 bg-white/5 p-2.5">
              <div className="flex items-center justify-between gap-2">
                <div className="text-sm text-white/90">{title}</div>
                <span className={`text-[10px] px-2 py-0.5 rounded-full border ${riskBadge(risk)}`}>
                  {risk || "UNKNOWN"}
                </span>
              </div>
              {item.description && <div className="mt-1 text-xs text-gray-400">{item.description}</div>}
              {isSayPreview && item.text && (
                <div className="mt-2 text-xs text-gray-300 line-clamp-3">{item.text}</div>
              )}
              {isTweetPreview && !!item.payload?.tweet_text && (
                <div className="mt-2">
                  <div className="text-[10px] text-blue-300 flex items-center gap-1">
                    <span>𝕏</span>
                    <span>{String(item.payload.tweet_text).length}/280</span>
                  </div>
                  <div className="mt-1 text-xs text-gray-200 bg-black/30 rounded-lg p-2 whitespace-pre-wrap">
                    {String(item.payload.tweet_text)}
                  </div>
                </div>
              )}
              {decision.reason && (
                <div className="mt-2 text-[11px] text-amber-200/80">理由: {decision.reason}</div>
              )}
              {decision.requires_confirmation && (
                <div className="mt-1 text-[11px] text-amber-200/70">要確認</div>
              )}
              <div className="mt-1.5 flex items-center gap-2">
                {!isSayPreview && (
                  <input
                    type="text"
                    value={pendingId ? (reasonById[pendingId] || "") : ""}
                    onChange={(e) => updateReason(pendingId, e.target.value)}
                    placeholder="理由（任意）"
                    className="flex-1 rounded-lg bg-black/30 px-2 py-1 text-xs text-gray-100 placeholder:text-gray-500"
                  />
                )}
                <button
                  onClick={() => postDecision(item, "approve")}
                  className="flex items-center gap-1 rounded-lg border border-emerald-500/40 bg-emerald-500/20 px-2 py-1 text-xs text-emerald-100"
                >
                  <Check size={12} /> 承認
                </button>
                <button
                  onClick={() => postDecision(item, "reject")}
                  className="flex items-center gap-1 rounded-lg border border-red-500/40 bg-red-500/20 px-2 py-1 text-xs text-red-100"
                >
                  <X size={12} /> 拒否
                </button>
              </div>
            </div>
          );
        })}
        {!loading && pending.length === 0 && (
          <div className="text-xs text-gray-400">保留中のアクションはありません。</div>
        )}
      </div>

      <div className="mt-1.5 border-t border-white/10 pt-1 flex flex-col min-h-0 shrink-0">
        <div className="flex items-center justify-between">
          <div className="text-[10px] text-gray-300">実行結果</div>
          <div className="flex items-center gap-1.5 text-[10px]">
            <button
              onClick={() => setResultTab("state")}
              className={`rounded-full border px-1 py-0 ${
                resultTab === "state"
                  ? "border-sky-400/50 text-sky-200 bg-sky-500/20"
                  : "border-white/10 text-gray-400"
              }`}
            >
              最新（state）
            </button>
            <button
              onClick={() => setResultTab("history")}
              className={`rounded-full border px-1 py-0 ${
                resultTab === "history"
                  ? "border-rose-400/50 text-rose-200 bg-rose-500/20"
                  : "border-white/10 text-gray-400"
              }`}
            >
              履歴（永続）
            </button>
          </div>
        </div>
        <div className="mt-0.5 space-y-0.5 overflow-y-auto pr-1 min-h-0 max-h-16">
          {(resultTab === "state" ? recentResults : recentHistoryResults).map((r, idx) => (
            <div key={`${r.action_id}-${idx}`} className="rounded-lg border border-white/10 bg-white/5 px-1 py-0.5">
              <div className="flex items-center justify-between text-[11px]">
                <span className="text-gray-200">{r.action_id}</span>
                <span className={`text-[10px] ${r.status === "success" ? "text-emerald-200" : "text-red-200"}`}>
                  {r.status}
                </span>
              </div>
              {r.source && (
                <div className="mt-0.5 text-[10px] text-gray-500">source: {r.source}</div>
              )}
              {r.result && typeof r.result === "object" && "message" in r.result && (
                <div className="mt-0.5 text-[10px] text-gray-400">{String(r.result.message)}</div>
              )}
            </div>
          ))}
          {resultTab === "state" && recentResults.length === 0 && (
            <div className="text-xs text-gray-400">まだ実行結果はありません。</div>
          )}
          {resultTab === "history" && recentHistoryResults.length === 0 && (
            <div className="text-xs text-gray-400">履歴はまだありません。</div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";
import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { VRMLoaderPlugin, VRMUtils, VRM } from '@pixiv/three-vrm';

// ── Gesture System Types ─────────────────────────────────────────

interface GestureKeyframe {
    bone: string;
    axis: 'x' | 'y' | 'z';
    target: number;
    duration: number;     // ms for this keyframe
    delay?: number;       // ms delay before this keyframe starts
}

interface GesturePreset {
    name: string;
    keyframes: GestureKeyframe[];
    totalDuration: number;
    returnDuration: number;
}

interface ActiveGesture {
    preset: GesturePreset;
    startTime: number;
    phase: 'play' | 'return';
    boneStates: Map<string, { axis: string; from: number; target: number }>;
}

// ── Built-in Gesture Presets ─────────────────────────────────────

const GESTURE_PRESETS: Record<string, GesturePreset> = {
    nod: {
        name: 'nod',
        keyframes: [
            { bone: 'head', axis: 'x', target: -0.18, duration: 200 },
            { bone: 'head', axis: 'x', target: 0.0, duration: 200 },
        ],
        totalDuration: 400,
        returnDuration: 200,
    },
    wave: {
        name: 'wave',
        keyframes: [
            { bone: 'rightUpperArm', axis: 'z', target: 0.3, duration: 300 },
            { bone: 'rightLowerArm', axis: 'z', target: -0.8, duration: 200, delay: 100 },
            { bone: 'rightLowerArm', axis: 'z', target: -1.2, duration: 200, delay: 300 },
            { bone: 'rightLowerArm', axis: 'z', target: -0.8, duration: 200, delay: 500 },
        ],
        totalDuration: 800,
        returnDuration: 400,
    },
    shrug: {
        name: 'shrug',
        keyframes: [
            { bone: 'leftUpperArm', axis: 'z', target: -1.0, duration: 350 },
            { bone: 'rightUpperArm', axis: 'z', target: 1.0, duration: 350 },
            { bone: 'head', axis: 'x', target: -0.08, duration: 300 },
            { bone: 'head', axis: 'z', target: 0.1, duration: 300 },
        ],
        totalDuration: 600,
        returnDuration: 400,
    },
    tilt_head: {
        name: 'tilt_head',
        keyframes: [
            { bone: 'head', axis: 'z', target: 0.18, duration: 400 },
            { bone: 'head', axis: 'x', target: -0.05, duration: 300 },
        ],
        totalDuration: 500,
        returnDuration: 400,
    },
    bow: {
        name: 'bow',
        keyframes: [
            { bone: 'spine', axis: 'x', target: -0.2, duration: 500 },
            { bone: 'head', axis: 'x', target: -0.15, duration: 400, delay: 100 },
        ],
        totalDuration: 700,
        returnDuration: 500,
    },
    point: {
        name: 'point',
        keyframes: [
            { bone: 'rightUpperArm', axis: 'z', target: 0.2, duration: 300 },
            { bone: 'rightLowerArm', axis: 'z', target: -0.3, duration: 250, delay: 100 },
        ],
        totalDuration: 500,
        returnDuration: 350,
    },
    fist_pump: {
        name: 'fist_pump',
        keyframes: [
            { bone: 'rightUpperArm', axis: 'z', target: 0.5, duration: 250 },
            { bone: 'rightLowerArm', axis: 'z', target: -1.5, duration: 200, delay: 100 },
            { bone: 'rightUpperArm', axis: 'z', target: 0.3, duration: 200, delay: 300 },
            { bone: 'rightUpperArm', axis: 'z', target: 0.5, duration: 200, delay: 500 },
        ],
        totalDuration: 700,
        returnDuration: 350,
    },
    clap: {
        name: 'clap',
        keyframes: [
            { bone: 'leftUpperArm', axis: 'z', target: -0.8, duration: 200 },
            { bone: 'rightUpperArm', axis: 'z', target: 0.8, duration: 200 },
            { bone: 'leftUpperArm', axis: 'z', target: -1.0, duration: 150, delay: 200 },
            { bone: 'rightUpperArm', axis: 'z', target: 1.0, duration: 150, delay: 200 },
            { bone: 'leftUpperArm', axis: 'z', target: -0.8, duration: 150, delay: 350 },
            { bone: 'rightUpperArm', axis: 'z', target: 0.8, duration: 150, delay: 350 },
        ],
        totalDuration: 600,
        returnDuration: 350,
    },
};

// ── Rest pose (default bone rotations) ───────────────────────────

const REST_POSE: Record<string, Record<string, number>> = {
    leftUpperArm:  { x: 0, y: 0, z: -1.3 },
    rightUpperArm: { x: 0, y: 0, z: 1.3 },
    leftLowerArm:  { x: 0, y: 0, z: 0 },
    rightLowerArm: { x: 0, y: 0, z: 0 },
    head:          { x: 0, y: 0, z: 0 },
    spine:         { x: 0, y: 0, z: 0 },
};

// ── Easing ────────────────────────────────────────────────────────

function easeInOut(t: number): number {
    return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
}

// ── Component ─────────────────────────────────────────────────────

interface AvatarProps {
    isTalking: boolean;
    emotion: string;
    isThinking?: boolean;
    stateTag?: string;
    gesture?: string;
    gestureTick?: number;
    audioVolume?: number;
}

export default function AvatarView({
    isTalking, emotion, isThinking = false, stateTag = "", gesture = "", gestureTick = 0, audioVolume,
}: AvatarProps) {
    const containerRef = useRef<HTMLDivElement>(null);
    const vrmRef = useRef<VRM | null>(null);
    const clockRef = useRef(new THREE.Clock());
    const emotionRef = useRef<string>(emotion);
    const stateRef = useRef<string>(stateTag);
    const thinkingRef = useRef<boolean>(isThinking);
    const audioVolumeRef = useRef<number>(0);
    const activeGestureRef = useRef<ActiveGesture | null>(null);
    const gestureQueueRef = useRef<string>("");
    const noiseRef = useRef({
        currentFreq: 1.0,
        targetFreq: 1.0,
        nextUpdateAt: 0,
        phase: 0,
        seed: 42.1337,
    });

    // ── Gesture trigger ──────────────────────────────────────────
    useEffect(() => {
        if (gesture) {
            gestureQueueRef.current = gesture;
        }
    }, [gesture, gestureTick]);

    useEffect(() => {
        emotionRef.current = emotion;
    }, [emotion]);

    useEffect(() => {
        stateRef.current = stateTag;
    }, [stateTag]);

    useEffect(() => {
        thinkingRef.current = isThinking;
    }, [isThinking]);

    useEffect(() => {
        audioVolumeRef.current = audioVolume ?? 0;
    }, [audioVolume]);

    // ── Main scene setup + animation loop ────────────────────────
    useEffect(() => {
        if (!containerRef.current) return;

        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x0f0f12);

        const camera = new THREE.PerspectiveCamera(30, containerRef.current.clientWidth / containerRef.current.clientHeight, 0.1, 20.0);
        camera.position.set(0.0, 1.3, 1.4);

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        containerRef.current.appendChild(renderer.domElement);

        const light = new THREE.DirectionalLight(0xffffff);
        light.position.set(1.0, 1.0, 1.0).normalize();
        scene.add(light);
        const ambient = new THREE.AmbientLight(0x404040);
        scene.add(ambient);

        const loader = new GLTFLoader();
        loader.register((parser) => new VRMLoaderPlugin(parser));

        loader.load(
            '/avatar.vrm',
            (gltf) => {
                const vrm = gltf.userData.vrm;
                VRMUtils.removeUnnecessaryVertices(gltf.scene);
                VRMUtils.combineSkeletons(gltf.scene);
                vrm.scene.rotation.y = 0;
                scene.add(vrm.scene);
                vrmRef.current = vrm;
            },
            () => { /* progress silenced */ },
            (error) => console.error("VRM Load Failed:", error)
        );

        const getMotionParams = () => {
            const state = (stateRef.current || "").toLowerCase();
            const emotionTag = (emotionRef.current || "").toLowerCase();
            const tag = state || emotionTag;
            const pondering = Boolean(thinkingRef.current) || tag === "pondering";

            let amplitude = 0.0045;
            let baseFrequency = 0.55;
            let jitter = 0.18;
            let damping = 0.08;

            if (tag === "consent") {
                amplitude = 0.0030; damping = 0.14; jitter = 0.08;
            }
            if (tag === "dissonance") {
                amplitude = 0.0060; baseFrequency = 0.8; jitter = 0.35; damping = 0.05;
            }
            if (pondering) {
                baseFrequency = 0.5; jitter = 0.12;
            }

            return { amplitude, baseFrequency, jitter, damping, pondering };
        };

        // ── Helper: get bone rest rotation for an axis ───────────
        const getRestValue = (boneName: string, axis: string): number => {
            return REST_POSE[boneName]?.[axis] ?? 0;
        };

        // ── Helper: get current bone rotation ────────────────────
        const getBoneRotation = (humanoid: any, boneName: string, axis: string): number => {
            const bone = humanoid.getNormalizedBoneNode(boneName);
            if (!bone) return getRestValue(boneName, axis);
            return (bone.rotation as any)[axis] as number;
        };

        // ── Helper: set bone rotation ────────────────────────────
        const setBoneRotation = (humanoid: any, boneName: string, axis: string, value: number) => {
            const bone = humanoid.getNormalizedBoneNode(boneName);
            if (bone) {
                (bone.rotation as any)[axis] = value;
            }
        };

        // ── Gesture update per frame ─────────────────────────────
        const updateGesture = (humanoid: any, now: number) => {
            // Check for new gesture in queue
            if (gestureQueueRef.current && !activeGestureRef.current) {
                const presetName = gestureQueueRef.current.toLowerCase();
                gestureQueueRef.current = "";
                const preset = GESTURE_PRESETS[presetName];
                if (preset) {
                    const boneStates = new Map<string, { axis: string; from: number; target: number }>();
                    for (const kf of preset.keyframes) {
                        const key = `${kf.bone}_${kf.axis}`;
                        if (!boneStates.has(key)) {
                            boneStates.set(key, {
                                axis: kf.axis,
                                from: getBoneRotation(humanoid, kf.bone, kf.axis),
                                target: kf.target,
                            });
                        }
                    }
                    activeGestureRef.current = {
                        preset,
                        startTime: now,
                        phase: 'play',
                        boneStates,
                    };
                }
            }

            const ag = activeGestureRef.current;
            if (!ag) return;

            const elapsed = (now - ag.startTime) * 1000; // ms

            if (ag.phase === 'play') {
                // Apply each keyframe
                for (const kf of ag.preset.keyframes) {
                    const delay = kf.delay ?? 0;
                    const kfStart = delay;
                    const kfEnd = delay + kf.duration;

                    const key = `${kf.bone}_${kf.axis}`;
                    const state = ag.boneStates.get(key);
                    if (!state) continue;

                    if (elapsed < kfStart) {
                        // Not started yet
                    } else if (elapsed >= kfEnd) {
                        setBoneRotation(humanoid, kf.bone, kf.axis, kf.target);
                        // Update last known target for this bone
                        state.target = kf.target;
                    } else {
                        const progress = easeInOut((elapsed - kfStart) / kf.duration);
                        const value = state.from + (kf.target - state.from) * progress;
                        setBoneRotation(humanoid, kf.bone, kf.axis, value);
                    }
                }

                // Transition to return phase
                if (elapsed >= ag.preset.totalDuration) {
                    ag.phase = 'return';
                    ag.startTime = now;
                    // Capture current bone positions as "from" for return
                    for (const kf of ag.preset.keyframes) {
                        const key = `${kf.bone}_${kf.axis}`;
                        const state = ag.boneStates.get(key);
                        if (state) {
                            state.from = getBoneRotation(humanoid, kf.bone, kf.axis);
                            state.target = getRestValue(kf.bone, kf.axis);
                        }
                    }
                }
            } else if (ag.phase === 'return') {
                const returnElapsed = (now - ag.startTime) * 1000;
                const returnDur = ag.preset.returnDuration;

                if (returnElapsed >= returnDur) {
                    // Done - restore rest pose for affected bones
                    for (const kf of ag.preset.keyframes) {
                        setBoneRotation(humanoid, kf.bone, kf.axis, getRestValue(kf.bone, kf.axis));
                    }
                    activeGestureRef.current = null;
                } else {
                    const progress = easeInOut(returnElapsed / returnDur);
                    const seen = new Set<string>();
                    for (const kf of ag.preset.keyframes) {
                        const key = `${kf.bone}_${kf.axis}`;
                        if (seen.has(key)) continue;
                        seen.add(key);
                        const state = ag.boneStates.get(key);
                        if (state) {
                            const value = state.from + (state.target - state.from) * progress;
                            setBoneRotation(humanoid, kf.bone, kf.axis, value);
                        }
                    }
                }
            }
        };

        // ── Set of bones currently controlled by gesture ─────────
        const isGestureControlling = (boneName: string, axis: string): boolean => {
            const ag = activeGestureRef.current;
            if (!ag) return false;
            return ag.boneStates.has(`${boneName}_${axis}`);
        };

        // ── Main animation loop ──────────────────────────────────
        const animate = () => {
            requestAnimationFrame(animate);
            const delta = clockRef.current.getDelta();
            const vrm = vrmRef.current;

            if (vrm) {
                const humanoid = vrm.humanoid;

                // Apply rest pose for non-gesture-controlled bones
                if (humanoid) {
                    if (!isGestureControlling('leftUpperArm', 'z')) {
                        const leftArm = humanoid.getNormalizedBoneNode('leftUpperArm');
                        if (leftArm) leftArm.rotation.z = -1.3;
                    }
                    if (!isGestureControlling('rightUpperArm', 'z')) {
                        const rightArm = humanoid.getNormalizedBoneNode('rightUpperArm');
                        if (rightArm) rightArm.rotation.z = 1.3;
                    }
                }

                vrm.update(delta);

                const t = clockRef.current.elapsedTime;
                const { amplitude, baseFrequency, jitter, damping, pondering } = getMotionParams();

                // Noise-based body sway
                if (t >= noiseRef.current.nextUpdateAt) {
                    const pseudo = Math.sin(t * 1.731 + noiseRef.current.seed) * 0.5 + 0.5;
                    noiseRef.current.targetFreq = Math.max(0.4, baseFrequency + (pseudo - 0.5) * jitter * 2.0);
                    const interval = 1.5 + (pseudo * 1.5);
                    noiseRef.current.nextUpdateAt = t + interval;
                }

                noiseRef.current.currentFreq += (noiseRef.current.targetFreq - noiseRef.current.currentFreq) * damping;
                noiseRef.current.phase += noiseRef.current.currentFreq * delta * Math.PI * 2.0;

                let amp = amplitude;
                if (pondering) {
                    const slowT = t * (Math.PI * 2.0) * 0.2;
                    const wave = 0.5 + 0.5 * Math.sin(slowT);
                    amp = amplitude * (0.3 + 0.7 * wave);
                }

                vrm.scene.rotation.z = Math.sin(noiseRef.current.phase) * amp;

                // Head motion (thinking) - only if gesture not controlling head
                if (humanoid) {
                    const headControlled = isGestureControlling('head', 'x') ||
                                           isGestureControlling('head', 'y') ||
                                           isGestureControlling('head', 'z');
                    if (!headControlled) {
                        const head = humanoid.getNormalizedBoneNode('head');
                        if (head) {
                            if (thinkingRef.current) {
                                head.rotation.y = Math.sin(t * 0.7) * 0.15;
                                head.rotation.x = -0.06 + Math.sin(t * 0.9) * 0.03;
                            } else {
                                head.rotation.x = 0;
                                head.rotation.y = 0;
                            }
                        }
                    }

                    // Gesture animation update
                    updateGesture(humanoid, t);
                }

                // Auto blink
                if (Math.random() < 0.005) {
                    vrm.expressionManager?.setValue('blink', 1.0);
                    setTimeout(() => vrm.expressionManager?.setValue('blink', 0.0), 100);
                }
            }

            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            camera.aspect = containerRef.current.clientWidth / containerRef.current.clientHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            renderer.dispose();
            if (containerRef.current?.contains(renderer.domElement)) {
                containerRef.current.removeChild(renderer.domElement);
            }
        };
    }, []);

    // ── Expression control ───────────────────────────────────────
    useEffect(() => {
        const vrm = vrmRef.current;
        if (!vrm || !vrm.expressionManager) return;

        const list = vrm.expressionManager.expressions;
        list.forEach(e => {
            if (e.expressionName !== 'blink' && e.expressionName !== 'aa') {
                vrm.expressionManager?.setValue(e.expressionName, 0);
            }
        });

        let targetExpression = 'neutral';
        if (emotion === 'happy') targetExpression = 'happy';
        if (emotion === 'sad') targetExpression = 'sad';
        if (emotion === 'angry') targetExpression = 'angry';
        if (emotion === 'surprised') targetExpression = 'surprised';
        if (emotion === 'consent') targetExpression = 'neutral';
        if (emotion === 'dissonance') targetExpression = 'neutral';
        if (emotion === 'pondering') targetExpression = 'neutral';

        if (vrm.expressionManager.getExpression(targetExpression)) {
            vrm.expressionManager.setValue(targetExpression, 1.0);
        } else {
            if (emotion === 'happy') vrm.expressionManager.setValue('joy', 1.0);
            else vrm.expressionManager.setValue('neutral', 1.0);
        }
    }, [emotion]);

    // ── Lip sync ─────────────────────────────────────────────────
    useEffect(() => {
        let frameId: number;
        let prevSmoothed = 0;
        const lipLoop = () => {
            const vrm = vrmRef.current;
            if (vrm && vrm.expressionManager) {
                const vol = audioVolumeRef.current;
                if (vol > 0.01) {
                    // Audio-driven lip sync
                    prevSmoothed += (vol - prevSmoothed) * 0.3;
                    vrm.expressionManager.setValue('aa', Math.min(prevSmoothed * 1.5, 1.0));
                } else if (isTalking) {
                    // Fallback: sin wave
                    prevSmoothed = 0;
                    const v = 0.2 + 0.4 * Math.sin(Date.now() / 60);
                    vrm.expressionManager.setValue('aa', v);
                } else {
                    prevSmoothed = 0;
                    vrm.expressionManager.setValue('aa', 0);
                }
            }
            frameId = requestAnimationFrame(lipLoop);
        };
        lipLoop();
        return () => cancelAnimationFrame(frameId);
    }, [isTalking]);

    return (
        <div className="w-full h-full glass-panel relative overflow-hidden rounded-2xl">
            <div ref={containerRef} className="w-full h-full" />
        </div>
    );
}

"use client";
import React, { useRef, useEffect } from 'react';
import { API_URL, apiClient, getStaticUrl, type ChatMessage } from '@/lib/apiClient';
import { ChatMessages, ChatInput } from '@/components/chat';
import { safeJsonParse } from '@/lib/types';
import {
    normalizeContent,
    extractSpeech,
    normalizeHistoryMessage,
    isLikelyDuplicateAppend,
    dedupeAdjacentDuplicateParagraphs,
} from '@/components/chat/messageNormalization';
import { useAudioPlayback } from '@/hooks/useAudioPlayback';
import { useVoiceMode } from '@/hooks/useVoiceMode';
import { useChatStore } from '@/lib/stores/chatStore';

interface ChatInterfaceProps {
    onStateChange: (isTalking: boolean, emotion: string, isThinking?: boolean) => void;
    onAgentStateChange?: (state: string) => void;
    onGestureChange?: (gesture: string) => void;
    onVolumeChange?: (volume: number) => void;
    agentMode: string;
}

export default function ChatInterface({ onStateChange, onAgentStateChange, onGestureChange, onVolumeChange, agentMode }: ChatInterfaceProps) {
    const {
        messages, setMessages, addMessage, updateMessageContent, upsertMessage, clearMessages,
        input, setInput, appendInput,
        isLoading, setIsLoading,
        threadId, setThreadId,
        currentEmotion, setCurrentEmotion,
        connectionState, setConnectionState,
        thinkingHint, setThinkingHint,
        selectedImage, setSelectedImage,
        isListening, setIsListening,
    } = useChatStore();

    // Refs to avoid stale closures in handleMessage callback
    const currentEmotionRef = useRef(currentEmotion);
    currentEmotionRef.current = currentEmotion;
    const thinkingHintRef = useRef(thinkingHint);
    thinkingHintRef.current = thinkingHint;

    // Stream Refs
    const aiMsgIdRef = useRef<string | null>(null);
    const aiTextRef = useRef<string>("");
    const isStreamingRef = useRef(false);
    const isThinkingRef = useRef(false);
    const lastEventAtRef = useRef<number>(0);
    const activeStreamIdRef = useRef<number>(0);
    const sseStreamIdRef = useRef<string | null>(null);
    const finalTextLockedRef = useRef<boolean>(false);
    const abortControllerRef = useRef<AbortController | null>(null);
    const currentStateRef = useRef<string>("");
    const ttsEsRef = useRef<EventSource | null>(null);
    const sendMessageRef = useRef<(text?: string) => Promise<void>>(async () => { });
    const micVadRef = useRef<any>(null);

    const {
        audioQueueRef,
        isPlayingRef,
        audioRef,
        interruptAudioPlayback,
        processAudioQueue,
    } = useAudioPlayback({
        onStateChange,
        onVolumeChange,
        currentEmotionRef,
        isThinkingRef,
        micVadRef,
    });

    const {
        voiceModeEnabled,
        voiceWsState,
        voiceError,
        sttPreview,
        toggleVoiceMode,
        cleanupVoiceRuntime,
    } = useVoiceMode({
        threadId,
        isLoading,
        interruptAudioPlayback,
        isPlayingRef,
        sendMessageRef,
        micVadRef,
    });

    const syncThinking = (next: boolean) => {
        isThinkingRef.current = next;
        onStateChange(isPlayingRef.current, currentEmotion, next);
    };

    const addSystemMessage = (content: string) => {
        addMessage({ id: newId(), role: 'system', content });
    };

    useEffect(() => {
        const timer = setInterval(() => {
            if (!isThinkingRef.current) return;
            const lastAt = lastEventAtRef.current || 0;
            if (Date.now() - lastAt > 30_000) {
                syncThinking(false);
                setConnectionState("stale");
                addSystemMessage("（通信が途切れたため、思考状態を解除しました）");
                const streamId = String(activeStreamIdRef.current || "");
                apiClient.reportStreamTimeout(
                    threadId || "default_thread",
                    streamId,
                    "SSE timeout / no events for 30s",
                );
            }
        }, 500);
        return () => clearInterval(timer);
    }, [threadId]);

    // Helper: Ensure IDs exist
    const ensureIds = (msgs: any[]): ChatMessage[] => {
        return msgs.map((m, i) => ({
            id: m.id || `hist-${Date.now()}-${i}`,
            ...m
        }));
    };

    // Helper: Generate new ID
    const newId = () => {
        if (typeof crypto !== 'undefined' && crypto.randomUUID) {
            return crypto.randomUUID();
        }
        return `msg-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    };

    // Initialize Thread & Load History
    useEffect(() => {
        const savedThreadId = "default_thread";
        setThreadId(savedThreadId);

        const loadHistory = async () => {
            if (isStreamingRef.current) return;

            try {
                const data = await apiClient.fetchHistory(savedThreadId);

                const hist = data?.history;
                if (Array.isArray(hist)) {
                    const cleaned = hist.map((m: any) => normalizeHistoryMessage(m));

                    // パフォーマンス: 表示件数を制限（UIだけ軽く、データはDBに全部ある）
                    const MAX_RENDER = 120;
                    setMessages(ensureIds(cleaned.slice(-MAX_RENDER)));
                }
            } catch (e) {
                console.error("[loadHistory] failed", e);
            }
        };
        loadHistory();

        return () => {
            cleanupVoiceRuntime();
        };
    }, []);

    // Scroll is handled inside ChatMessages component


    // --- Speech Recognition ---
    const recognitionRef = useRef<any>(null);

    useEffect(() => {
        if (typeof window !== 'undefined') {
            const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
            if (SpeechRecognition) {
                const recognition = new SpeechRecognition();
                recognition.continuous = true;
                recognition.interimResults = true;
                recognition.lang = 'ja-JP';

                recognition.onresult = (event: any) => {
                    let finalTranscript = '';

                    for (let i = event.resultIndex; i < event.results.length; ++i) {
                        if (event.results[i].isFinal) {
                            finalTranscript += event.results[i][0].transcript;
                        }
                    }

                    if (finalTranscript) {
                        appendInput(finalTranscript);
                    }
                };

                recognition.onerror = (event: any) => {
                    console.error("Speech Recognition Error:", event.error);
                    setIsListening(false);
                };

                recognition.onend = () => {
                    if (isListening) {
                        setIsListening(false);
                    }
                };

                recognitionRef.current = recognition;
            }
        }
    }, []);

    const toggleListening = () => {
        if (!recognitionRef.current) {
            alert("このブラウザは音声認識をサポートしていません。Chromeを使用してください。");
            return;
        }

        if (isListening) {
            recognitionRef.current.stop();
            setIsListening(false);
        } else {
            recognitionRef.current.start();
            setIsListening(true);
        }
    };

    const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => setSelectedImage(reader.result as string);
            reader.readAsDataURL(file);
        }
    };

    // --- Safe AI Message Updates (ID-based) ---
    function beginAiMessage() {
        const id = newId();
        aiMsgIdRef.current = id;
        aiTextRef.current = "";
        addMessage({ id, role: 'ai', content: '' });
    }

    function appendAiChunk(chunk: string) {
        if (!chunk) return;
        if (isLikelyDuplicateAppend(aiTextRef.current, chunk)) {
            return;
        }
        const id = aiMsgIdRef.current;
        if (!id) {
            const nextId = newId();
            aiMsgIdRef.current = nextId;
            aiTextRef.current = chunk;
            addMessage({ id: nextId, role: 'ai', content: chunk });
            return;
        }
        aiTextRef.current += chunk;
        aiTextRef.current = dedupeAdjacentDuplicateParagraphs(aiTextRef.current);
        updateMessageContent(id, aiTextRef.current);
    }

    async function backfillLastAssistantMessage(attempt: number = 0) {
        try {
            const data = await apiClient.fetchRecentHistory(threadId || "default_thread", 10);
            const hist = Array.isArray(data?.history) ? data.history : [];
            const last = [...hist].reverse().find((m: any) => m?.role === "assistant" || m?.role === "ai");
            if (!last) {
                if (attempt < 2) {
                    setTimeout(() => backfillLastAssistantMessage(attempt + 1), 250);
                }
                return;
            }
            const text = extractSpeech(normalizeContent(last.content));
            if (!text) {
                if (attempt < 2) {
                    setTimeout(() => backfillLastAssistantMessage(attempt + 1), 250);
                }
                return;
            }
            if (!aiMsgIdRef.current) {
                beginAiMessage();
            }
            appendAiChunk(text);
        } catch (e) {
            console.warn("[backfillLastAssistantMessage] failed", e);
        }
    }

    const handleMessage = React.useCallback((msg: any) => {
        try {
            if (msg?.stream_id != null) {
                const got = String(msg.stream_id);
                if (!sseStreamIdRef.current) {
                    sseStreamIdRef.current = got;
                } else if (got !== String(sseStreamIdRef.current)) {
                    console.warn("[SSE DROP] stream_id mismatch", {
                        got,
                        expected: String(sseStreamIdRef.current),
                        type: msg.type,
                    });
                    return;
                }
            }
            lastEventAtRef.current = Date.now();
            setConnectionState("ok");

            if (msg.type === "text") {
                if (finalTextLockedRef.current) {
                    // Authoritative final_result already arrived for this turn.
                    // Ignore trailing text chunks to keep UI aligned with committed final_text.
                    return;
                }
                const text = String(msg.content ?? "");
                if (text.trim() === "WAIT") {
                    // WAIT is handled as a UI hint; don't render as chat text
                    return;
                }
                if (isThinkingRef.current) {
                    syncThinking(false);
                }
                appendAiChunk(text);
                if (thinkingHintRef.current) {
                    setThinkingHint(null);
                }

                // 感情分析 (一時的に無効化)
                /*
                try {
                    if (AFFECT_REGEX.global) {
                        const matches = [...aiTextRef.current.matchAll(AFFECT_REGEX)];
                        if (matches.length > 0) {
                            const lastEmotion = matches[matches.length - 1][1];
                            if (lastEmotion !== currentEmotion) {
                                setCurrentEmotion(lastEmotion);
                                onStateChange(true, lastEmotion);
                            }
                        }
                    }
                } catch (e) {
                    console.error("Affect parse failed:", e);
                }
                */

            } else if (msg.type === "state") {
                const tag = String(msg.tag || "").toLowerCase();
                if (tag) {
                    currentStateRef.current = tag;
                    onAgentStateChange?.(tag);
                    onStateChange(true, currentEmotionRef.current, isThinkingRef.current);
                }
            } else if (msg.type === "emotion") {
                const tag = String(msg.tag || "").toLowerCase();
                if (tag) {
                    setCurrentEmotion(tag);
                    onStateChange(true, tag, isThinkingRef.current);
                }
            } else if (msg.type === "gesture") {
                const tag = String(msg.tag || "").toLowerCase();
                if (tag) {
                    onGestureChange?.(tag);
                }
            } else if (msg.type === "thinking") {
                const nextThinking = Boolean(msg.value ?? msg.thinking ?? true);
                syncThinking(nextThinking);
            } else if (msg.type === "audio") {
                // Accept audio only from the active main stream.
                // Legacy /tts_events payloads can arrive without stream_id and replay stale audio.
                if (msg?.stream_id == null) {
                    console.warn("[AUDIO EVT] dropped: missing stream_id", msg);
                    return;
                }
                // Support both msg.url and msg.data?.url
                const url = msg.url || msg.data?.url;
                const audioText = String(msg?.data?.text_content ?? "").trim();
                if (!finalTextLockedRef.current && audioText) {
                    if (!aiMsgIdRef.current) {
                        beginAiMessage();
                    }
                    const id = aiMsgIdRef.current;
                    aiTextRef.current = audioText;
                    if (id) updateMessageContent(id, audioText);
                    finalTextLockedRef.current = true;
                }
                if (url) {
                    if (String(url).includes("<") || String(url).includes(">")) {
                        console.warn("[AUDIO EVT] invalid url:", url);
                        return;
                    }
                    // getStaticUrlで統一的にURL組み立て
                    let audioUrl = getStaticUrl(url);
                    // Cache buster
                    audioUrl = audioUrl.includes("?")
                        ? `${audioUrl}&t=${Date.now()}`
                        : `${audioUrl}?t=${Date.now()}`;
                    audioQueueRef.current.push(audioUrl);
                    processAudioQueue();
                } else {
                    console.warn("[AUDIO EVT] missing url:", msg);
                }
            } else if (msg.type === "dream") {
                const dreamMsg: ChatMessage = {
                    id: msg.dream_id || `dream_${Date.now()}`,
                    role: 'system',
                    content: msg.text || '',
                    kind: 'dream',
                    meta: { mood: msg.mood, created_at: msg.created_at },
                };
                upsertMessage(dreamMsg);
            } else if (msg.type === "error") {
                console.error("Stream Error:", msg.content);
                addMessage({ id: newId(), role: 'system', content: `エラー: ${msg.content}` });
            } else if (msg.type === "event" && msg.name === "final_result") {
                const payload = msg.payload || {};
                const ft = String(payload.final_text ?? "");
                console.info("[SSE final_result] len=%d merge_mode=%s", ft.length, payload.merge_mode);
                if (ft.trim() && ft.trim() !== "WAIT") {
                    if (!aiMsgIdRef.current) {
                        beginAiMessage();
                    }
                    const id = aiMsgIdRef.current;
                    aiTextRef.current = ft;
                    if (id) updateMessageContent(id, ft);
                    finalTextLockedRef.current = true;
                }
            } else if (msg.type === "event" && msg.name === "thinking_hint") {
                setThinkingHint(msg.payload || {});
            } else if (
                msg.type === "event" &&
                (
                    msg.name === "hold_request" ||
                    msg.name === "hold_cancelled" ||
                    msg.name === "action_proposed" ||
                    msg.name === "action_approved" ||
                    msg.name === "action_blocked"
                )
            ) {
                if (typeof window !== "undefined") {
                    window.dispatchEvent(
                        new CustomEvent("phase5-action-event", {
                            detail: { name: msg.name, payload: msg.payload || {} },
                        })
                    );
                }
            } else if (msg.type === "done") {
                if (isThinkingRef.current) {
                    syncThinking(false);
                }
                if (!aiTextRef.current.trim()) {
                    console.warn("[SSE done] aiText is empty — triggering backfill. finalTextLocked=", finalTextLockedRef.current);
                    backfillLastAssistantMessage();
                }
            } else {
                console.warn("[SSE NOTICE] unknown event type", msg?.type, msg);
            }
        } catch (e) {
            console.error("handleMessage crashed:", e, msg);
        }
    }, [onAgentStateChange, onStateChange]);

    useEffect(() => {
        const tid = threadId || "default_thread";
        if (typeof EventSource === "undefined") return;
        // Audio now arrives on the main /stream_chat SSE.
        // Keep legacy /tts_events disabled by default to avoid stale backlog playback.
        const enableLegacyTtsEvents = String(process.env.NEXT_PUBLIC_ENABLE_TTS_EVENTS ?? "0") === "1";
        if (!enableLegacyTtsEvents) {
            if (ttsEsRef.current) {
                ttsEsRef.current.close();
                ttsEsRef.current = null;
            }
            return;
        }

        if (ttsEsRef.current) {
            ttsEsRef.current.close();
            ttsEsRef.current = null;
        }

        const sseUrl = `${API_URL}/tts_events/${tid}`;
        const es = new EventSource(sseUrl);
        ttsEsRef.current = es;

        es.onmessage = (e) => {
            try {
                const msg = JSON.parse(e.data);
                handleMessage(msg);
            } catch (err) {
                console.warn("[TTS_ES] bad json", e.data);
            }
        };

        es.onerror = (e) => {
            console.warn("[TTS_ES] error", e);
            // EventSource should auto-reconnect, but add manual reconnect as fallback
            if (es.readyState === EventSource.CLOSED) {
                es.close();
                if (ttsEsRef.current === es) ttsEsRef.current = null;
                // Reconnect after 2 seconds
                setTimeout(() => {
                    if (!ttsEsRef.current) {
                        const newEs = new EventSource(sseUrl);
                        ttsEsRef.current = newEs;
                        newEs.onmessage = es.onmessage;
                        newEs.onerror = es.onerror;
                    }
                }, 2000);
            }
        };

        return () => {
            es.close();
            if (ttsEsRef.current === es) ttsEsRef.current = null;
        };
    }, [threadId, handleMessage]);

    const sendMessage = async (overrideText?: string) => {
        const textToSend = overrideText ?? input;
        if (!textToSend.trim() && !selectedImage) return;
        // Voice mode (overrideText) can interrupt an active stream;
        // keyboard input respects the loading guard.
        if (!overrideText && isLoading) return;

        onAgentStateChange?.("");
        syncThinking(false);
        setThinkingHint(null);
        finalTextLockedRef.current = false;
        if (abortControllerRef.current) {
            abortControllerRef.current.abort();
        }

        // Stop current audio and clear queue
        if (audioRef.current) {
            audioRef.current.pause();
            audioRef.current = null;
        }
        isPlayingRef.current = false;
        audioQueueRef.current = [];

        activeStreamIdRef.current += 1;
        sseStreamIdRef.current = null;

        const id = newId();
        const userMsg: ChatMessage = { id, role: 'user', content: textToSend };
        if (selectedImage) userMsg.image = selectedImage;

        addMessage(userMsg);
        setInput("");
        setSelectedImage(null);
        setIsLoading(true);
        isStreamingRef.current = true;
        const controller = new AbortController();
        abortControllerRef.current = controller;
        const streamId = activeStreamIdRef.current;
        lastEventAtRef.current = Date.now();
        setConnectionState("ok");

        try {
            const response = await apiClient.streamChat({
                text: userMsg.content,
                threadId: threadId || "default_thread",
                voiceId: "14",
                imageData: userMsg.image,
                mode: agentMode,
                streamId: String(streamId),
                messageId: userMsg.id,
            }, controller.signal);

            if (!response.body) throw new Error("No response body");

            const reader = response.body.getReader();
            const decoder = new TextDecoder("utf-8");
            let buffer = "";
            let chunkCount = 0;

            // Start AI message safely
            beginAiMessage();

            while (true) {
                const { done, value } = await reader.read();
                if (done) break;

                chunkCount++;
                const decoded = decoder.decode(value, { stream: true });
                buffer += decoded;
                buffer = buffer.replace(/\r\n/g, "\n");

                let idx;
                while ((idx = buffer.indexOf("\n\n")) !== -1) {
                    const rawEvent = buffer.slice(0, idx);
                    buffer = buffer.slice(idx + 2);

                    const dataLines = rawEvent
                        .split("\n")
                        .filter((l) => l.startsWith("data:"))
                        .map((l) => l.slice(5).trim());

                    if (dataLines.length === 0) continue;

                    const jsonStr = dataLines.join("\n");
                    try {
                        let msg: Record<string, unknown>;
                        const parsed = safeJsonParse<unknown>(jsonStr, null);
                        if (parsed === null || typeof parsed !== "object") {
                            msg = { type: "text", content: typeof parsed === "string" ? parsed : jsonStr };
                        } else {
                            msg = parsed as Record<string, unknown>;
                            if (!msg.type && typeof msg.text === "string") {
                                msg = { type: "text", content: msg.text, stream_id: msg.stream_id };
                            }
                        }
                        // Pass ALL events to handleMessage (including audio)
                        handleMessage(msg);

                    } catch (e) {
                        console.error("Bad SSE JSON head:", jsonStr.slice(0, 200));
                        console.error("Bad SSE JSON tail:", jsonStr.slice(-200));
                    }
                }
            }

        } catch (e) {
            console.error("Chat Error:", e);
            addMessage({ id: newId(), role: 'system', content: '接続エラーが発生しました' });
        } finally {
            // Only clean up if this is still the active stream.
            // A newer sendMessage() call may have incremented activeStreamIdRef.
            if (streamId === activeStreamIdRef.current) {
                setIsLoading(false);
                isStreamingRef.current = false;
                if (isThinkingRef.current) {
                    syncThinking(false);
                }
                onStateChange(false, currentEmotionRef.current, isThinkingRef.current);
            }
        }
    };
    sendMessageRef.current = sendMessage;

    const clearChat = async () => {
        if (isLoading) return;
        const ok = window.confirm("チャット履歴を削除しますか？");
        if (!ok) return;
        try {
            await apiClient.clearHistory(threadId || "default_thread");
        } catch (e) {
            console.error("Clear history failed", e);
        } finally {
            clearMessages();
            aiMsgIdRef.current = null;
            aiTextRef.current = "";
        }
    };

    return (
        <div className="flex flex-col h-full w-full max-w-4xl mx-auto p-2 sm:p-4 relative overflow-hidden box-border">
            {/* Header */}
            <div className="flex items-center justify-between mb-2 px-1">
                <div className="flex items-center gap-2">
                    <div className="text-xs text-gray-500">Chat</div>
                    {thinkingHint && (
                        <div
                            className="text-[11px] px-2 py-0.5 rounded-full border border-amber-500/30 text-amber-200/80 bg-amber-900/20"
                            title={JSON.stringify(thinkingHint)}
                        >
                            thinking…
                        </div>
                    )}
                </div>
                <button
                    onClick={clearChat}
                    className="text-xs text-red-400 hover:text-red-300 border border-red-500/30 px-2 py-1 rounded-lg"
                >
                    履歴削除
                </button>
            </div>
            {connectionState === "stale" && (
                <div className="mb-2 px-2 py-1 rounded-lg text-xs text-amber-200 bg-amber-900/40 border border-amber-500/30">
                    通信が不安定なため、思考状態を解除しました。再同期中…
                </div>
            )}
            {/* Messages */}
            <ChatMessages />

            {/* Input */}
            <ChatInput
                onToggleListening={toggleListening}
                onSendMessage={() => sendMessage()}
                onImageSelect={handleImageSelect}
                voiceModeEnabled={voiceModeEnabled}
                voiceWsState={voiceWsState}
                voiceError={voiceError}
                sttPreview={sttPreview}
                onToggleVoiceMode={toggleVoiceMode}
            />
        </div>
    );
}

"use client";

import React, { useCallback, useEffect, useRef, useState } from "react";
import { apiClient } from "@/lib/apiClient";

type DrawCommand =
  | { cmd: "fill"; color: string }
  | { cmd: "line"; x1: number; y1: number; x2: number; y2: number; brush: number; color: string };

type SessionState = {
  active: boolean;
  session_id?: string | null;
  planned_count?: number;
  sent_count?: number;
  rejected_count?: number;
  stop_reason?: string | null;
  max_strokes?: number;
};

const CANVAS_W = 800;
const CANVAS_H = 500;

export default function DrawLab() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const observeTimerRef = useRef<number | null>(null);
  const pollTimerRef = useRef<number | null>(null);
  const [prompt, setPrompt] = useState("抽象的で静かな夜の線画");
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [running, setRunning] = useState(false);
  const [sinceSeq, setSinceSeq] = useState(0);
  const [status, setStatus] = useState<SessionState>({ active: false });
  const [error, setError] = useState<string | null>(null);

  const getCtx = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return null;
    const ctx = canvas.getContext("2d");
    return ctx;
  }, []);

  const clearCanvas = useCallback(() => {
    const ctx = getCtx();
    if (!ctx) return;
    ctx.fillStyle = "#0b1020";
    ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
  }, [getCtx]);

  useEffect(() => {
    clearCanvas();
  }, [clearCanvas]);

  const applyCommand = useCallback(
    (command: DrawCommand) => {
      const ctx = getCtx();
      if (!ctx) return;
      if (command.cmd === "fill") {
        ctx.fillStyle = command.color;
        ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
        return;
      }
      if (command.cmd === "line") {
        ctx.lineCap = "round";
        ctx.lineJoin = "round";
        ctx.strokeStyle = command.color;
        ctx.lineWidth = Math.max(1, Math.min(64, command.brush));
        ctx.beginPath();
        ctx.moveTo(command.x1, command.y1);
        ctx.lineTo(command.x2, command.y2);
        ctx.stroke();
      }
    },
    [getCtx]
  );

  const stopLoopTimers = useCallback(() => {
    if (observeTimerRef.current) {
      window.clearInterval(observeTimerRef.current);
      observeTimerRef.current = null;
    }
    if (pollTimerRef.current) {
      window.clearInterval(pollTimerRef.current);
      pollTimerRef.current = null;
    }
  }, []);

  const stopSession = useCallback(
    async (emergency = false) => {
      stopLoopTimers();
      setRunning(false);
      try {
        if (sessionId) await apiClient.drawSessionStop(sessionId, emergency);
      } catch (_e) {
        // noop
      }
      try {
        const st = await apiClient.drawSessionState();
        setStatus(st as SessionState);
      } catch { /* ignore */ }
    },
    [sessionId, stopLoopTimers]
  );

  const postObservation = useCallback(async () => {
    if (!sessionId) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    try {
      const imageData = canvas.toDataURL("image/jpeg", 0.55);
      await apiClient.drawObserve(sessionId, imageData);
    } catch (_e) {
      // noop
    }
  }, [sessionId]);

  const pollCommands = useCallback(async () => {
    if (!sessionId) return;
    try {
      const payload = await apiClient.drawCommands(sessionId, sinceSeq, 100) as Record<string, any>;
      const items = Array.isArray(payload.items) ? payload.items : [];
      for (const item of items) {
        applyCommand((item?.command || {}) as DrawCommand);
      }
      if (typeof payload.next_seq === "number") {
        setSinceSeq(payload.next_seq);
      }
      setStatus((prev) => ({
        ...prev,
        active: Boolean(payload.active),
        stop_reason: payload.stop_reason || null,
        planned_count: payload.planned_count as number | undefined,
        sent_count: payload.sent_count as number | undefined,
        rejected_count: payload.rejected_count as number | undefined,
      }));
      if (payload.active === false) {
        stopLoopTimers();
        setRunning(false);
      }
    } catch (_e) {
      // noop
    }
  }, [applyCommand, sessionId, sinceSeq, stopLoopTimers]);

  const startSession = useCallback(async () => {
    setError(null);
    stopLoopTimers();
    setSinceSeq(0);
    clearCanvas();
    try {
      const state = (await apiClient.drawSessionStart({
        prompt,
        width: CANVAS_W,
        height: CANVAS_H,
        interval_sec: 1.2,
        max_strokes: 48,
        timeout_sec: 180,
      })) as SessionState;
      const sid = state.session_id ? String(state.session_id) : null;
      if (!sid) throw new Error("session_id missing");
      setSessionId(sid);
      setStatus(state);
      setRunning(Boolean(state.active));

      observeTimerRef.current = window.setInterval(() => {
        void postObservation();
      }, 1200);
      pollTimerRef.current = window.setInterval(() => {
        void pollCommands();
      }, 350);
    } catch (e: any) {
      setError(e?.message || "start failed");
      setRunning(false);
    }
  }, [clearCanvas, pollCommands, postObservation, prompt, stopLoopTimers]);

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && running) {
        e.preventDefault();
        void stopSession(true);
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [running, stopSession]);

  useEffect(() => {
    return () => {
      stopLoopTimers();
    };
  }, [stopLoopTimers]);

  return (
    <div className="h-full w-full p-4 space-y-3">
      <div className="flex flex-wrap items-center gap-2">
        <input
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="ニアに描いてほしい方向性"
          className="min-w-[260px] flex-1 rounded-lg border border-white/10 bg-black/30 px-3 py-2 text-sm text-gray-100 placeholder:text-gray-500"
        />
        <button
          onClick={() => void startSession()}
          className="rounded-lg border border-cyan-500/40 bg-cyan-500/20 px-3 py-2 text-xs text-cyan-100"
        >
          開始
        </button>
        <button
          onClick={() => void stopSession(false)}
          className="rounded-lg border border-amber-500/40 bg-amber-500/20 px-3 py-2 text-xs text-amber-100"
        >
          停止
        </button>
        <button
          onClick={clearCanvas}
          className="rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-xs text-gray-200"
        >
          キャンバス初期化
        </button>
      </div>

      <div className="text-xs text-gray-400 flex flex-wrap gap-4">
        <span>session: {sessionId || "-"}</span>
        <span>active: {running ? "yes" : "no"}</span>
        <span>planned/sent/rejected: {status.planned_count || 0}/{status.sent_count || 0}/{status.rejected_count || 0}</span>
        <span>max_strokes: {status.max_strokes || 0}</span>
        <span>stop_reason: {status.stop_reason || "-"}</span>
        <span className="text-rose-300">Escで緊急停止</span>
      </div>
      {error && <div className="text-xs text-rose-300">{error}</div>}

      <div className="rounded-xl border border-white/10 bg-black/20 p-2">
        <canvas
          ref={canvasRef}
          width={CANVAS_W}
          height={CANVAS_H}
          className="w-full max-w-[960px] rounded-lg bg-[#0b1020]"
        />
      </div>

      <div className="text-xs text-gray-500">
        命令層: draw planner（backend）/ 安全実行: 別プロセス validator / 観測: 1.2秒ごと / 停止: Esc・上限・タイムアウト
      </div>
    </div>
  );
}

"use client";
import React, { useEffect, useState, useCallback, useRef } from "react";
import {
  Gamepad2,
  Heart,
  Drumstick,
  MapPin,
  Package,
  Users,
  Cloud,
  CloudRain,
  Sun,
  Moon,
  Sunrise,
  Sunset,
  Wifi,
  WifiOff,
  Send,
  ChevronDown,
  ChevronRight,
} from "lucide-react";
import { apiClient } from "@/lib/apiClient";
import type { GameStateData, GameEvent } from "@/lib/types";

export default function GamePanel() {
  const [state, setState] = useState<GameStateData | null>(null);
  const [events, setEvents] = useState<GameEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [chatMsg, setChatMsg] = useState("");
  const [invOpen, setInvOpen] = useState(false);
  const eventsEndRef = useRef<HTMLDivElement>(null);

  // Poll game state
  const fetchState = useCallback(async () => {
    try {
      const data = await apiClient.fetchGameState();
      setState(data as unknown as GameStateData);
    } catch {
      setState(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchState();
    const interval = setInterval(fetchState, 2000);
    return () => clearInterval(interval);
  }, [fetchState]);

  // WebSocket for events
  useEffect(() => {
    let ws: WebSocket | null = null;
    let mounted = true;

    const connect = () => {
      // バックエンド直結（Next.js proxy は WS 非対応）
      const wsScheme = window.location.protocol === "https:" ? "wss" : "ws";
      const backendPort = process.env.NEXT_PUBLIC_BACKEND_PORT || "8000";
      const wsUrl = `${wsScheme}://${window.location.hostname}:${backendPort}/api/game/ws`;
      ws = new WebSocket(wsUrl);

      ws.onmessage = (ev) => {
        try {
          const event = JSON.parse(ev.data) as GameEvent;
          if (event.type === "ping") return;
          if (mounted) {
            setEvents((prev) => [...prev.slice(-49), event]);
          }
        } catch { /* ignore */ }
      };

      ws.onclose = () => {
        if (mounted) setTimeout(connect, 5000);
      };

      ws.onerror = () => ws?.close();
    };

    connect();
    return () => {
      mounted = false;
      ws?.close();
    };
  }, []);

  // Auto-scroll events
  useEffect(() => {
    eventsEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [events]);

  const sendChat = async () => {
    if (!chatMsg.trim()) return;
    await apiClient.executeGameAction("chat", { message: chatMsg });
    setChatMsg("");
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full text-gray-400">
        <Gamepad2 className="w-8 h-8 animate-pulse mr-3" />
        Loading...
      </div>
    );
  }

  const connected = state?.connected ?? false;

  if (!connected) {
    return (
      <div className="flex flex-col items-center justify-center h-full gap-4 text-gray-400">
        <WifiOff className="w-12 h-12" />
        <p className="text-lg">Minecraft Bot 未接続</p>
        <p className="text-sm text-gray-500">
          minecraft-bot を起動して、Minecraft サーバーに接続してください
        </p>
        <button
          onClick={() => apiClient.connectGame()}
          className="px-4 py-2 bg-green-600/20 text-green-400 rounded-lg hover:bg-green-600/30 transition"
        >
          接続
        </button>
      </div>
    );
  }

  const pos = state?.position;
  const timePeriod = state?.time?.period ?? "unknown";
  const isRaining = state?.time?.isRaining ?? false;

  const TimeIcon =
    timePeriod === "night" ? Moon :
    timePeriod === "sunrise" ? Sunrise :
    timePeriod === "sunset" ? Sunset : Sun;

  return (
    <div className="flex flex-col h-full p-4 gap-3 overflow-y-auto">
      {/* Header */}
      <div className="flex items-center gap-3">
        <Gamepad2 className="w-6 h-6 text-green-400" />
        <h2 className="text-lg font-bold">Minecraft</h2>
        <div className="flex items-center gap-1 ml-auto text-xs text-green-400">
          <Wifi className="w-4 h-4" />
          Connected
        </div>
      </div>

      {/* Status Grid */}
      <div className="grid grid-cols-2 gap-3">
        {/* Health */}
        <div className="glass-panel rounded-xl p-3">
          <div className="flex items-center gap-2 text-sm text-gray-400 mb-1">
            <Heart className="w-4 h-4 text-red-400" />
            HP
          </div>
          <div className="flex items-center gap-2">
            <div className="flex-1 bg-gray-700/50 rounded-full h-2">
              <div
                className="bg-red-500 rounded-full h-2 transition-all"
                style={{ width: `${((state?.health ?? 20) / 20) * 100}%` }}
              />
            </div>
            <span className="text-sm font-mono">{state?.health ?? 20}/20</span>
          </div>
        </div>

        {/* Food */}
        <div className="glass-panel rounded-xl p-3">
          <div className="flex items-center gap-2 text-sm text-gray-400 mb-1">
            <Drumstick className="w-4 h-4 text-amber-400" />
            Food
          </div>
          <div className="flex items-center gap-2">
            <div className="flex-1 bg-gray-700/50 rounded-full h-2">
              <div
                className="bg-amber-500 rounded-full h-2 transition-all"
                style={{ width: `${((state?.food ?? 20) / 20) * 100}%` }}
              />
            </div>
            <span className="text-sm font-mono">{state?.food ?? 20}/20</span>
          </div>
        </div>
      </div>

      {/* Position & Environment */}
      <div className="glass-panel rounded-xl p-3">
        <div className="flex items-center gap-4 text-sm">
          <div className="flex items-center gap-1">
            <MapPin className="w-4 h-4 text-blue-400" />
            <span className="font-mono">
              {pos ? `${pos.x}, ${pos.y}, ${pos.z}` : "???"}
            </span>
          </div>
          <div className="text-gray-400">{state?.biome ?? "unknown"}</div>
          <div className="flex items-center gap-1 ml-auto">
            <TimeIcon className="w-4 h-4 text-yellow-400" />
            <span className="text-gray-400">{timePeriod}</span>
            {isRaining && <CloudRain className="w-4 h-4 text-blue-400 ml-1" />}
          </div>
        </div>
      </div>

      {/* Inventory */}
      <div className="glass-panel rounded-xl p-3">
        <button
          onClick={() => setInvOpen(!invOpen)}
          className="flex items-center gap-2 text-sm w-full"
        >
          <Package className="w-4 h-4 text-purple-400" />
          <span>Inventory ({state?.inventory?.length ?? 0})</span>
          {invOpen ? (
            <ChevronDown className="w-4 h-4 ml-auto" />
          ) : (
            <ChevronRight className="w-4 h-4 ml-auto" />
          )}
        </button>
        {invOpen && (
          <div className="mt-2 grid grid-cols-2 gap-1 text-xs text-gray-300 max-h-40 overflow-y-auto">
            {(state?.inventory ?? []).map((item, i) => (
              <div key={i} className="flex justify-between px-2 py-1 bg-white/5 rounded">
                <span>{item.name}</span>
                <span className="text-gray-500">x{item.count}</span>
              </div>
            ))}
            {(!state?.inventory || state.inventory.length === 0) && (
              <div className="col-span-2 text-center text-gray-500 py-2">Empty</div>
            )}
          </div>
        )}
      </div>

      {/* Nearby Entities */}
      {state?.nearbyEntities && state.nearbyEntities.length > 0 && (
        <div className="glass-panel rounded-xl p-3">
          <div className="flex items-center gap-2 text-sm mb-2">
            <Users className="w-4 h-4 text-cyan-400" />
            <span>Nearby ({state.nearbyEntities.length})</span>
          </div>
          <div className="space-y-1 text-xs max-h-32 overflow-y-auto">
            {state.nearbyEntities.slice(0, 8).map((e, i) => (
              <div key={i} className="flex justify-between px-2 py-1 bg-white/5 rounded">
                <span className={e.type === "player" ? "text-green-400" : "text-gray-300"}>
                  {e.name}
                </span>
                <span className="text-gray-500">{e.distance}m</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Event Feed */}
      <div className="glass-panel rounded-xl p-3 flex-1 min-h-[120px]">
        <div className="text-sm text-gray-400 mb-2">Events</div>
        <div className="space-y-1 text-xs max-h-40 overflow-y-auto">
          {events.length === 0 && (
            <div className="text-gray-500 text-center py-4">No events yet</div>
          )}
          {events.map((ev, i) => (
            <div key={i} className="flex gap-2 px-2 py-1 bg-white/5 rounded">
              <span className="text-gray-500 font-mono">
                {new Date(ev.ts).toLocaleTimeString()}
              </span>
              <span className="text-yellow-400">{ev.type}</span>
              <span className="text-gray-300 truncate">
                {formatEventData(ev)}
              </span>
            </div>
          ))}
          <div ref={eventsEndRef} />
        </div>
      </div>

      {/* Quick Chat */}
      <div className="flex gap-2">
        <input
          type="text"
          value={chatMsg}
          onChange={(e) => setChatMsg(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && sendChat()}
          placeholder="ゲーム内チャット..."
          className="flex-1 bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-sm outline-none focus:border-blue-500/50"
        />
        <button
          onClick={sendChat}
          className="px-3 py-2 bg-blue-600/20 text-blue-400 rounded-lg hover:bg-blue-600/30 transition"
        >
          <Send className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}

function formatEventData(ev: GameEvent): string {
  const d = ev.data || {};
  switch (ev.type) {
    case "chat":
      return `[${d.username}] ${d.message}`;
    case "health_change":
      return `HP: ${d.health} Food: ${d.food}`;
    case "damage":
      return `Took damage (HP: ${d.health})`;
    case "death":
      return "Died!";
    case "collect":
      return `Collected ${d.item}`;
    case "entity_spawn":
      return `${d.name} appeared (${d.distance}m)`;
    case "entity_gone":
      return `${d.name} left`;
    case "weather":
      return d.isRaining ? "Rain started" : "Rain stopped";
    default:
      return JSON.stringify(d).slice(0, 60);
  }
}

