"use client";
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { apiClient } from '@/lib/apiClient';
import { Loader2, ZoomIn, ZoomOut, RefreshCw } from 'lucide-react';

type MemoryCategory = 'memory' | 'policy' | 'identity' | 'public' | 'decision' | 'other';
type TimeRange = 'all' | '7d' | '30d' | '90d';

interface GraphNode {
    id: string;
    label: string;
    full_text: string;
    timestamp: string;
    source: string;
    category?: MemoryCategory;
    degree?: number;
    x?: number;
    y?: number;
    vx?: number;
    vy?: number;
}

interface GraphEdge {
    source: string;
    target: string;
    weight: number;
}

interface GraphData {
    nodes: GraphNode[];
    edges: GraphEdge[];
    error?: string;
}

const CATEGORY_LABEL: Record<MemoryCategory, string> = {
    memory: '記憶',
    policy: '方針',
    identity: '自己定義',
    public: '公開/配信',
    decision: '判断',
    other: 'その他',
};

const CATEGORY_COLOR: Record<MemoryCategory, string> = {
    memory: '#38bdf8',
    policy: '#f59e0b',
    identity: '#34d399',
    public: '#f97316',
    decision: '#f43f5e',
    other: '#a1a1aa',
};

const categoryKeywords: Array<{ category: MemoryCategory; words: string[] }> = [
    { category: 'memory', words: ['覚えて', '記録', '保存', 'メモ', '忘れない'] },
    { category: 'policy', words: ['設定', 'ルール', '方針', '今後', 'これから'] },
    { category: 'identity', words: ['名前', '呼び方', 'identity', 'origin', 'ニア'] },
    { category: 'public', words: ['配信', '公開', '視聴者', 'sns', '投稿', '拡散'] },
    { category: 'decision', words: ['決めて', '判断', '結論', '最適', 'おすすめ', 'ランキング'] },
];
const SIMULATION_DURATION_MS = 4500;

// ── Barnes-Hut Quad-tree for O(n log n) repulsion ──

interface QuadBody { x: number; y: number; mass: number }

interface QuadNode {
    x: number; y: number;          // center of mass
    mass: number;
    size: number;                   // side length of this cell
    cx: number; cy: number;         // cell center
    body: QuadBody | null;          // leaf body (null for internal)
    nw: QuadNode | null;
    ne: QuadNode | null;
    sw: QuadNode | null;
    se: QuadNode | null;
}

function createQuadNode(cx: number, cy: number, size: number): QuadNode {
    return { x: 0, y: 0, mass: 0, size, cx, cy, body: null, nw: null, ne: null, sw: null, se: null };
}

const MAX_QUAD_DEPTH = 20;

function insertBody(node: QuadNode, body: QuadBody, depth: number = 0): void {
    if (node.mass === 0) {
        // Empty leaf — place body here
        node.body = body;
        node.x = body.x;
        node.y = body.y;
        node.mass = body.mass;
        return;
    }

    // 深さ上限: 同一座標のノードが無限再帰するのを防止
    if (depth >= MAX_QUAD_DEPTH) {
        const totalMass = node.mass + body.mass;
        node.x = (node.x * node.mass + body.x * body.mass) / totalMass;
        node.y = (node.y * node.mass + body.y * body.mass) / totalMass;
        node.mass = totalMass;
        return;
    }

    // If this is a leaf with one body, subdivide
    if (node.body !== null) {
        subdivide(node);
        const old = node.body;
        node.body = null;
        insertIntoChild(node, old, depth);
    }

    // Insert new body into correct child
    insertIntoChild(node, body, depth);

    // Update center of mass
    const totalMass = node.mass + body.mass;
    node.x = (node.x * node.mass + body.x * body.mass) / totalMass;
    node.y = (node.y * node.mass + body.y * body.mass) / totalMass;
    node.mass = totalMass;
}

function subdivide(node: QuadNode): void {
    const hs = node.size / 2;
    const qs = node.size / 4;
    node.nw = createQuadNode(node.cx - qs, node.cy - qs, hs);
    node.ne = createQuadNode(node.cx + qs, node.cy - qs, hs);
    node.sw = createQuadNode(node.cx - qs, node.cy + qs, hs);
    node.se = createQuadNode(node.cx + qs, node.cy + qs, hs);
}

function insertIntoChild(node: QuadNode, body: QuadBody, depth: number = 0): void {
    const west = body.x < node.cx;
    const north = body.y < node.cy;
    const child = north ? (west ? node.nw! : node.ne!) : (west ? node.sw! : node.se!);
    insertBody(child, body, depth + 1);
}

const THETA = 0.8; // Barnes-Hut opening angle

function computeRepulsion(
    node: QuadNode,
    body: QuadBody,
    k: number,
    outFx: { v: number },
    outFy: { v: number },
): void {
    if (node.mass === 0) return;
    const dx = body.x - node.x;
    const dy = body.y - node.y;
    const dist = Math.sqrt(dx * dx + dy * dy) || 1;

    // If leaf with single body and it's the same body, skip
    if (node.body !== null && dx === 0 && dy === 0) return;

    // Barnes-Hut: if cell is far enough, treat as single body
    if (node.body !== null || node.size / dist < THETA) {
        const force = (k * k * node.mass) / dist;
        outFx.v += (dx / dist) * force * 0.01;
        outFy.v += (dy / dist) * force * 0.01;
        return;
    }

    // Otherwise recurse into children
    if (node.nw) computeRepulsion(node.nw, body, k, outFx, outFy);
    if (node.ne) computeRepulsion(node.ne, body, k, outFx, outFy);
    if (node.sw) computeRepulsion(node.sw, body, k, outFx, outFy);
    if (node.se) computeRepulsion(node.se, body, k, outFx, outFy);
}

function inferCategory(node: GraphNode): MemoryCategory {
    const text = `${node.source || ''} ${node.full_text || ''}`.toLowerCase();
    for (const rule of categoryKeywords) {
        if (rule.words.some((w) => text.includes(w.toLowerCase()))) {
            return rule.category;
        }
    }
    return 'other';
}

export default function MemoryGraph() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [data, setData] = useState<GraphData | null>(null);
    const [loading, setLoading] = useState(true);
    const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
    const [zoom, setZoom] = useState(1);
    const [threshold, setThreshold] = useState(0.7);
    const [categoryFilter, setCategoryFilter] = useState<'all' | MemoryCategory>('all');
    const [timeRange, setTimeRange] = useState<TimeRange>('30d');
    const [showLabels, setShowLabels] = useState(true);
    const [isSimulating, setIsSimulating] = useState(true);
    const nodesRef = useRef<GraphNode[]>([]);

    const fetchData = async () => {
        setLoading(true);
        try {
            const graphData = await apiClient.fetchMemoryGraph(threshold, 100) as unknown as GraphData;
            {
                const degreeMap: Record<string, number> = {};
                (graphData.edges || []).forEach((edge: GraphEdge) => {
                    degreeMap[edge.source] = (degreeMap[edge.source] || 0) + 1;
                    degreeMap[edge.target] = (degreeMap[edge.target] || 0) + 1;
                });
                // ランダムな初期位置を設定
                graphData.nodes.forEach((node: GraphNode) => {
                    node.x = Math.random() * 600 + 100;
                    node.y = Math.random() * 400 + 100;
                    node.vx = 0;
                    node.vy = 0;
                    node.category = inferCategory(node);
                    node.degree = degreeMap[node.id] || 0;
                });
                setData(graphData);
                nodesRef.current = graphData.nodes;
                setIsSimulating(true);
            }
        } catch (e) {
            console.error('Failed to fetch graph:', e);
        }
        setLoading(false);
    };

    const filteredData = useMemo(() => {
        if (!data) return null;

        let filteredNodes = [...data.nodes];
        if (categoryFilter !== 'all') {
            filteredNodes = filteredNodes.filter((n) => n.category === categoryFilter);
        }

        if (timeRange !== 'all') {
            const nowMs = Date.now();
            const days = timeRange === '7d' ? 7 : timeRange === '30d' ? 30 : 90;
            const cutoffMs = nowMs - days * 24 * 60 * 60 * 1000;
            filteredNodes = filteredNodes.filter((n) => {
                if (!n.timestamp) return false;
                const ts = Date.parse(n.timestamp);
                if (Number.isNaN(ts)) return false;
                return ts >= cutoffMs;
            });
        }

        const nodeSet = new Set(filteredNodes.map((n) => n.id));
        const nodes = data.nodes.filter((n) => nodeSet.has(n.id));
        const edges = data.edges.filter((e) => nodeSet.has(e.source) && nodeSet.has(e.target));
        return { ...data, nodes, edges };
    }, [data, categoryFilter, timeRange]);

    const topNodes = useMemo(() => {
        const nodes = filteredData?.nodes || [];
        return [...nodes].sort((a, b) => (b.degree || 0) - (a.degree || 0)).slice(0, 8);
    }, [filteredData]);

    useEffect(() => {
        fetchData();
    }, [threshold]);

    // Force-directed simulation
    useEffect(() => {
        if (!filteredData || filteredData.nodes.length === 0) return;

        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const nodes = filteredData.nodes;
        const edges = filteredData.edges;
        nodesRef.current = nodes;

        let animationId: number;
        const startedAt = performance.now();

        // Pre-build node lookup map for O(1) edge resolution
        const nodeMap = new Map<string, GraphNode>();
        nodes.forEach(n => nodeMap.set(n.id, n));

        const simulate = () => {
            const k = 50; // Ideal spring length
            const gravity = 0.1;
            const centerX = canvas.width / 2;
            const centerY = canvas.height / 2;

            // Build Quad-tree for Barnes-Hut repulsion (O(n log n))
            const treeSize = Math.max(canvas.width, canvas.height) * 2;
            const root = createQuadNode(centerX, centerY, treeSize);
            nodes.forEach(node => {
                insertBody(root, { x: node.x!, y: node.y!, mass: 1 });
            });

            // Apply forces
            nodes.forEach((node) => {
                // Center gravity
                node.vx! += (centerX - node.x!) * gravity * 0.01;
                node.vy! += (centerY - node.y!) * gravity * 0.01;

                // Repulsion via Quad-tree (Barnes-Hut)
                const fx = { v: 0 };
                const fy = { v: 0 };
                computeRepulsion(root, { x: node.x!, y: node.y!, mass: 1 }, k, fx, fy);
                node.vx! += fx.v;
                node.vy! += fy.v;
            });

            // Attraction along edges (O(E))
            edges.forEach(edge => {
                const source = nodeMap.get(edge.source);
                const target = nodeMap.get(edge.target);
                if (!source || !target) return;

                const dx = target.x! - source.x!;
                const dy = target.y! - source.y!;
                const dist = Math.sqrt(dx * dx + dy * dy) || 1;
                const force = (dist - k) * edge.weight * 0.01;

                source.vx! += (dx / dist) * force;
                source.vy! += (dy / dist) * force;
                target.vx! -= (dx / dist) * force;
                target.vy! -= (dy / dist) * force;
            });

            // Update positions with damping
            nodes.forEach(node => {
                node.vx! *= 0.9;
                node.vy! *= 0.9;
                node.x! += node.vx!;
                node.y! += node.vy!;
                node.x = Math.max(50, Math.min(canvas.width - 50, node.x!));
                node.y = Math.max(50, Math.min(canvas.height - 50, node.y!));
            });

            // Draw
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.save();
            ctx.scale(zoom, zoom);

            // Draw edges
            edges.forEach(edge => {
                const source = nodeMap.get(edge.source);
                const target = nodeMap.get(edge.target);
                if (!source || !target) return;

                ctx.beginPath();
                ctx.moveTo(source.x!, source.y!);
                ctx.lineTo(target.x!, target.y!);
                ctx.strokeStyle = `rgba(100, 180, 255, ${edge.weight * 0.5})`;
                ctx.lineWidth = edge.weight * 2;
                ctx.stroke();
            });

            // Draw nodes
            nodes.forEach(node => {
                const category = node.category || 'other';
                const degree = node.degree || 0;
                const radius = 6 + Math.min(7, degree * 0.6);
                ctx.beginPath();
                ctx.arc(node.x!, node.y!, radius, 0, Math.PI * 2);
                ctx.fillStyle = node === selectedNode ? '#93c5fd' : CATEGORY_COLOR[category];
                ctx.fill();
                ctx.strokeStyle = node === selectedNode ? '#1d4ed8' : '#0f172a';
                ctx.lineWidth = node === selectedNode ? 2 : 1.5;
                ctx.stroke();
            });

            if (showLabels) {
                const topNodeIds = new Set(topNodes.map((n) => n.id));
                nodes.forEach((node) => {
                    if (!topNodeIds.has(node.id) && node !== selectedNode) return;
                    ctx.font = '12px sans-serif';
                    ctx.fillStyle = '#e5e7eb';
                    ctx.textAlign = 'center';
                    const label = node.label.length > 20 ? `${node.label.slice(0, 20)}...` : node.label;
                    ctx.fillText(label, node.x!, node.y! - 14);
                });
            }

            ctx.restore();
            if (performance.now() - startedAt >= SIMULATION_DURATION_MS) {
                setIsSimulating(false);
                return;
            }
            animationId = requestAnimationFrame(simulate);
        };

        setIsSimulating(true);
        simulate();

        return () => cancelAnimationFrame(animationId);
    }, [filteredData, zoom, selectedNode, showLabels, topNodes]);

    // Handle click
    const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const rect = canvas.getBoundingClientRect();
        const x = (e.clientX - rect.left) / zoom;
        const y = (e.clientY - rect.top) / zoom;

        const nodes = nodesRef.current;
        const clicked = nodes.find(node => {
            const dx = node.x! - x;
            const dy = node.y! - y;
            return Math.sqrt(dx * dx + dy * dy) < 15;
        });

        setSelectedNode(clicked || null);
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <Loader2 className="w-8 h-8 animate-spin text-blue-400" />
            </div>
        );
    }

    if (!data || data.nodes.length === 0) {
        return (
            <div className="flex items-center justify-center h-64 text-gray-500">
                記憶データがありません
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full">
            {/* Controls */}
            <div className="flex items-center gap-4 p-4 border-b border-white/10 flex-wrap">
                <div className="flex items-center gap-2">
                    <button onClick={() => setZoom(z => Math.max(0.5, z - 0.1))} className="p-2 glass rounded-lg hover:bg-white/10">
                        <ZoomOut className="w-4 h-4" />
                    </button>
                    <span className="text-sm text-gray-400">{Math.round(zoom * 100)}%</span>
                    <button onClick={() => setZoom(z => Math.min(2, z + 0.1))} className="p-2 glass rounded-lg hover:bg-white/10">
                        <ZoomIn className="w-4 h-4" />
                    </button>
                </div>
                <div className="flex items-center gap-2">
                    <span className="text-sm text-gray-400">類似度閾値:</span>
                    <input
                        type="range"
                        min="0.5"
                        max="0.95"
                        step="0.05"
                        value={threshold}
                        onChange={(e) => setThreshold(parseFloat(e.target.value))}
                        className="w-24"
                    />
                    <span className="text-sm text-blue-400">{threshold.toFixed(2)}</span>
                </div>
                <div className="flex items-center gap-2">
                    <span className="text-sm text-gray-400">分類:</span>
                    <select
                        value={categoryFilter}
                        onChange={(e) => setCategoryFilter(e.target.value as 'all' | MemoryCategory)}
                        className="rounded-lg bg-black/30 px-2 py-1 text-xs text-gray-200 border border-white/10"
                    >
                        <option value="all">全て</option>
                        <option value="memory">記憶</option>
                        <option value="policy">方針</option>
                        <option value="identity">自己定義</option>
                        <option value="public">公開/配信</option>
                        <option value="decision">判断</option>
                        <option value="other">その他</option>
                    </select>
                </div>
                <div className="flex items-center gap-2">
                    <span className="text-sm text-gray-400">期間:</span>
                    <select
                        value={timeRange}
                        onChange={(e) => setTimeRange(e.target.value as TimeRange)}
                        className="rounded-lg bg-black/30 px-2 py-1 text-xs text-gray-200 border border-white/10"
                    >
                        <option value="7d">7日</option>
                        <option value="30d">30日</option>
                        <option value="90d">90日</option>
                        <option value="all">全期間</option>
                    </select>
                </div>
                <label className="text-xs text-gray-400 flex items-center gap-2">
                    <input
                        type="checkbox"
                        checked={showLabels}
                        onChange={(e) => setShowLabels(e.target.checked)}
                    />
                    重要ノードにラベル表示
                </label>
                <button onClick={fetchData} className="p-2 glass rounded-lg hover:bg-white/10">
                    <RefreshCw className="w-4 h-4" />
                </button>
                <span className={`text-xs ${isSimulating ? 'text-amber-300' : 'text-emerald-300'}`}>
                    {isSimulating ? '配置を計算中…' : '配置を固定'}
                </span>
                <div className="text-sm text-gray-500 ml-auto">
                    {(filteredData?.nodes.length || 0)} nodes / {(filteredData?.edges.length || 0)} edges
                </div>
            </div>
            <div className="px-4 py-2 text-xs text-gray-400 border-b border-white/10 flex flex-wrap gap-3">
                {(Object.keys(CATEGORY_LABEL) as MemoryCategory[]).map((key) => (
                    <span key={key} className="inline-flex items-center gap-1">
                        <span className="inline-block w-2 h-2 rounded-full" style={{ backgroundColor: CATEGORY_COLOR[key] }} />
                        {CATEGORY_LABEL[key]}
                    </span>
                ))}
            </div>

            {/* Canvas */}
            <div className="flex-1 relative">
                <canvas
                    ref={canvasRef}
                    width={800}
                    height={500}
                    onClick={handleCanvasClick}
                    className="w-full h-full bg-black/30 rounded-lg cursor-crosshair"
                />
            </div>

            {/* Selected node info */}
            {selectedNode && (
                <div className="p-4 border-t border-white/10 bg-black/30">
                    <h4 className="font-semibold text-blue-300 mb-2">選択された記憶</h4>
                    <p className="text-sm text-gray-300">{selectedNode.full_text}</p>
                    <p className="text-xs text-gray-500 mt-2">
                        分類: {CATEGORY_LABEL[selectedNode.category || 'other']} | 接続数: {selectedNode.degree || 0}
                    </p>
                    <p className="text-xs text-gray-500 mt-1">
                        Source: {selectedNode.source} | {selectedNode.timestamp}
                    </p>
                </div>
            )}
        </div>
    );
}

"use client";
import React from 'react';
import { Settings, MessageSquare, Database, User, Mic, Moon, Sparkles, Eye, EyeOff, BarChart3, AlertTriangle, Brush, Gamepad2, Video } from 'lucide-react';
import { apiClient } from '@/lib/apiClient';
import { clsx } from 'clsx';
import type { ActionIssue } from '@/lib/types';

interface SidebarProps {
    activeTab: string;
    setActiveTab: (tab: string) => void;
}

const SYSTEM_TOKEN = process.env.NEXT_PUBLIC_SYSTEM_TOKEN || "";

export default function Sidebar({ activeTab, setActiveTab }: SidebarProps) {
    const tabs = [
        { id: 'chat', icon: MessageSquare, label: 'チャット' },
        { id: 'memories', icon: Database, label: '記憶データベース' },
        { id: 'stats', icon: BarChart3, label: '統計' },
        { id: 'action_issues', icon: AlertTriangle, label: '失敗/却下' },
        { id: 'draw_lab', icon: Brush, label: 'お絵描きPoC' },
        { id: 'game', icon: Gamepad2, label: 'ゲーム' },
        { id: 'video', icon: Video, label: '動画' },
        { id: 'profile', icon: User, label: 'プロフィール' },
        { id: 'identity', icon: User, label: 'アイデンティティ' },
        { id: 'settings', icon: Settings, label: '設定' },
    ];


    const [visionEnabled, setVisionEnabled] = React.useState(false);
    const [actionIssues, setActionIssues] = React.useState<ActionIssue[]>([]);
    const [systemTokenInput, setSystemTokenInput] = React.useState("");

    React.useEffect(() => {
        const stored =
            typeof window !== "undefined" ? window.localStorage.getItem("system_token") || "" : "";
        const initialToken = (stored || SYSTEM_TOKEN || "").trim();
        setSystemTokenInput(initialToken);
        apiClient.setSystemToken(initialToken || null);

        apiClient.fetchStatus()
            .then(data => {
                if (typeof data.vision_enabled === 'boolean') {
                    setVisionEnabled(data.vision_enabled);
                }
            })
            .catch(console.error);
    }, []);

    React.useEffect(() => {
        let cancelled = false;
        const fetchIssues = async () => {
            try {
                const data = await apiClient.fetchActionIssues("default_thread", "ERROR,REJECTED", 20);
                if (!cancelled) {
                    setActionIssues(Array.isArray(data?.items) ? data.items : []);
                }
            } catch (e) {
                if (!cancelled) {
                    setActionIssues([]);
                }
            }
        };
        fetchIssues();

        const handler = (ev: Event) => {
            const detail = (ev as CustomEvent).detail || {};
            if (!detail?.name) return;
            fetchIssues();
        };
        if (typeof window !== "undefined") {
            window.addEventListener("phase5-action-event", handler as EventListener);
        }

        return () => {
            cancelled = true;
            if (typeof window !== "undefined") {
                window.removeEventListener("phase5-action-event", handler as EventListener);
            }
        };
    }, []);

    const saveSystemToken = () => {
        const token = systemTokenInput.trim();
        if (typeof window !== "undefined") {
            if (token) {
                window.localStorage.setItem("system_token", token);
            } else {
                window.localStorage.removeItem("system_token");
            }
        }
        apiClient.setSystemToken(token || SYSTEM_TOKEN || null);
    };

    const clearSystemToken = () => {
        if (typeof window !== "undefined") {
            window.localStorage.removeItem("system_token");
        }
        setSystemTokenInput("");
        apiClient.setSystemToken(SYSTEM_TOKEN || null);
    };

    const toggleVision = async () => {
        const newState = !visionEnabled;
        setVisionEnabled(newState);
        try {
            await apiClient.systemVision(newState);
        } catch (e) {
            console.error(e);
            setVisionEnabled(!newState);
        }
    };

    return (
        <div className="w-20 lg:w-64 h-full glass-panel flex flex-col items-center lg:items-start py-6 gap-2 z-20 transition-all duration-300">
            <div className="mb-8 px-0 lg:px-6 w-full flex items-center justify-center lg:justify-start gap-3">
                <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-blue-500 to-cyan-400 flex items-center justify-center shadow-lg shadow-blue-500/30">
                    <Mic className="text-white w-6 h-6" />
                </div>
                <h1 className="hidden lg:block font-bold text-xl tracking-wide bg-gradient-to-r from-white to-gray-400 bg-clip-text text-transparent">
                    AI Nia(ニア)
                </h1>
            </div>

            <nav className="flex-1 w-full px-2 flex flex-col gap-2">
                {tabs.map((tab) => {
                    const Icon = tab.icon;
                    const isActive = activeTab === tab.id;
                    return (
                        <React.Fragment key={tab.id}>
                            <button
                                onClick={() => setActiveTab(tab.id)}
                                className={clsx(
                                    "w-full flex items-center gap-3 p-3 rounded-xl transition-all duration-200 group active:scale-95",
                                    isActive
                                        ? "bg-primary/20 text-primary border border-primary/20 shadow-[0_0_15px_rgba(59,130,246,0.2)]"
                                        : "text-gray-400 hover:bg-white/5 hover:text-gray-200"
                                )}
                            >
                                <Icon className={clsx("w-6 h-6", isActive && "text-blue-400")} />
                                <span className="hidden lg:block font-medium">{tab.label}</span>
                                {isActive && (
                                    <div className="lg:hidden absolute left-1 w-1 h-8 bg-blue-500 rounded-r-full" />
                                )}
                            </button>
                            {tab.id === "stats" && actionIssues.length > 0 && (
                                <div className="mx-1 my-1 rounded-xl border border-rose-500/20 bg-rose-900/10 px-2 py-1 text-[10px] text-rose-200/80">
                                    失敗/却下: {actionIssues.length}件
                                </div>
                            )}
                        </React.Fragment>
                    );
                })}
            </nav>

            <div className="w-full px-4 my-2 border-t border-white/5" />

            <div className="w-full px-2 flex flex-col gap-2">
                <button
                    onClick={async () => {
                        if (!confirm("睡眠サイクル（記憶の整理）を開始しますか？\nしばらく応答できなくなります。")) return;
                        try {
                            await apiClient.systemSleep();
                            alert("おやすみなさい。睡眠サイクルを開始しました。");
                        }
                        catch (e) { console.error(e); alert("失敗しました。"); }
                    }}
                    className="w-full flex items-center gap-3 p-3 rounded-xl text-gray-400 hover:bg-purple-500/10 hover:text-purple-300 transition-all active:scale-95"
                    title="睡眠モード"
                >
                    <Moon className="w-6 h-6 text-purple-400" />
                    <span className="hidden lg:block font-medium">睡眠 (Sleep)</span>
                </button>

                <button
                    onClick={toggleVision}
                    className={clsx(
                        "w-full flex items-center gap-3 p-3 rounded-xl transition-all active:scale-95",
                        visionEnabled
                            ? "text-green-400 bg-green-500/10 hover:bg-green-500/20"
                            : "text-gray-400 hover:bg-white/5 hover:text-gray-200"
                    )}
                    title={visionEnabled ? "視覚ON" : "視覚OFF"}
                >
                    {visionEnabled ? <Eye className="w-6 h-6" /> : <EyeOff className="w-6 h-6" />}
                    <span className="hidden lg:block font-medium">視覚 (Vision)</span>
                </button>

                <button
                    onClick={async () => {
                        if (!confirm("週次定例（進化プロセス）を開始しますか？\n直近1週間のログを分析します。")) return;
                        try {
                            await apiClient.systemReflect();
                            alert("振り返りを開始しました。ログを確認してください。");
                        }
                        catch (e) { console.error(e); alert("失敗しました。"); }
                    }}
                    className="w-full flex items-center gap-3 p-3 rounded-xl text-gray-400 hover:bg-yellow-500/10 hover:text-yellow-300 transition-all active:scale-95"
                    title="進化プロセス"
                >
                    <Sparkles className="w-6 h-6 text-yellow-400" />
                    <span className="hidden lg:block font-medium">進化 (Evolve)</span>
                </button>
            </div>

            <div className="hidden lg:block w-full px-3 mt-2">
                <div className="rounded-xl border border-white/10 bg-black/30 p-2">
                    <div className="text-[10px] text-gray-400 mb-1">Admin Token</div>
                    <input
                        type="password"
                        value={systemTokenInput}
                        onChange={(e) => setSystemTokenInput(e.target.value)}
                        placeholder="X-System-Token"
                        className="w-full rounded-md bg-black/40 border border-white/10 px-2 py-1 text-[11px] text-gray-200 placeholder:text-gray-500"
                    />
                    <div className="mt-2 flex gap-1">
                        <button
                            onClick={saveSystemToken}
                            className="flex-1 rounded-md border border-sky-400/30 bg-sky-500/20 px-2 py-1 text-[10px] text-sky-100 hover:bg-sky-500/30 transition"
                        >
                            保存
                        </button>
                        <button
                            onClick={clearSystemToken}
                            className="flex-1 rounded-md border border-white/15 bg-white/5 px-2 py-1 text-[10px] text-gray-300 hover:bg-white/10 transition"
                        >
                            クリア
                        </button>
                    </div>
                </div>
            </div>

            <div className="mt-auto p-4 text-xs text-gray-600 hidden lg:block text-center">
                v2.0.0 Alpha
            </div>
        </div>
    );
}

"use client";
import React, { useState, useRef, useCallback } from "react";
import {
  Video,
  Upload,
  Play,
  BookOpen,
  MessageCircle,
  Loader2,
  X,
  CheckCircle,
  AlertCircle,
  Link,
  FileVideo,
} from "lucide-react";
import { apiClient } from "@/lib/apiClient";

type Mode = "react" | "learn";
type Source = "file" | "url";

interface AnalyzeResult {
  mode: string;
  title?: string;
  duration?: number;
  scenes?: string[];
  frame_count?: number;
  strategies?: string[];
  memory_ids?: string[];
  success?: boolean;
}

export default function VideoPanel() {
  const [source, setSource] = useState<Source>("url");
  const [file, setFile] = useState<File | null>(null);
  const [url, setUrl] = useState("");
  const [mode, setMode] = useState<Mode>("react");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<AnalyzeResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFile = useCallback((f: File) => {
    const ext = f.name.split(".").pop()?.toLowerCase();
    if (!ext || !["mp4", "webm", "mkv", "avi", "mov"].includes(ext)) {
      setError(`非対応の形式: .${ext}`);
      return;
    }
    if (f.size > 200 * 1024 * 1024) {
      setError("ファイルサイズが大きすぎます（上限200MB）");
      return;
    }
    setFile(f);
    setError(null);
    setResult(null);
  }, []);

  const onDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setDragOver(false);
      const f = e.dataTransfer.files[0];
      if (f) handleFile(f);
    },
    [handleFile],
  );

  const canAnalyze =
    source === "file" ? !!file : url.trim().length > 0;

  const analyze = async () => {
    if (!canAnalyze) return;
    setLoading(true);
    setError(null);
    setResult(null);
    try {
      let res: AnalyzeResult;
      if (source === "url") {
        res = await apiClient.analyzeVideoUrl(url.trim(), mode);
      } else {
        res = await apiClient.analyzeVideo(file!, mode);
      }
      setResult(res);
    } catch (e: any) {
      setError(e?.message || "解析に失敗しました");
    } finally {
      setLoading(false);
    }
  };

  const clear = () => {
    setFile(null);
    setUrl("");
    setResult(null);
    setError(null);
  };

  return (
    <div className="flex flex-col h-full p-4 gap-4 overflow-y-auto">
      {/* Header */}
      <div className="flex items-center gap-3">
        <Video className="w-6 h-6 text-purple-400" />
        <h2 className="text-lg font-bold">動画解析</h2>
      </div>

      {/* Mode Toggle */}
      <div className="flex gap-2">
        <button
          onClick={() => setMode("react")}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm transition ${
            mode === "react"
              ? "bg-purple-600/20 text-purple-300 border border-purple-500/30"
              : "bg-white/5 text-gray-400 hover:bg-white/10"
          }`}
        >
          <MessageCircle className="w-4 h-4" />
          リアクション
        </button>
        <button
          onClick={() => setMode("learn")}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm transition ${
            mode === "learn"
              ? "bg-blue-600/20 text-blue-300 border border-blue-500/30"
              : "bg-white/5 text-gray-400 hover:bg-white/10"
          }`}
        >
          <BookOpen className="w-4 h-4" />
          学習
        </button>
      </div>

      <p className="text-xs text-gray-500">
        {mode === "react"
          ? "動画を見てニアが感想を返します"
          : "ゲームプレイ動画から戦略を抽出し、記憶に保存します"}
      </p>

      {/* Source Toggle: URL / File */}
      <div className="flex gap-2">
        <button
          onClick={() => { setSource("url"); setError(null); }}
          className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs transition ${
            source === "url"
              ? "bg-white/10 text-white border border-white/20"
              : "text-gray-500 hover:text-gray-300"
          }`}
        >
          <Link className="w-3.5 h-3.5" />
          URL (YouTube等)
        </button>
        <button
          onClick={() => { setSource("file"); setError(null); }}
          className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs transition ${
            source === "file"
              ? "bg-white/10 text-white border border-white/20"
              : "text-gray-500 hover:text-gray-300"
          }`}
        >
          <FileVideo className="w-3.5 h-3.5" />
          ファイル
        </button>
      </div>

      {/* URL Input */}
      {source === "url" && (
        <div className="space-y-2">
          <div className="flex gap-2">
            <input
              type="text"
              value={url}
              onChange={(e) => { setUrl(e.target.value); setError(null); setResult(null); }}
              onKeyDown={(e) => e.key === "Enter" && canAnalyze && !loading && analyze()}
              placeholder="https://www.youtube.com/watch?v=..."
              className="flex-1 bg-white/5 border border-white/10 rounded-lg px-3 py-2.5 text-sm outline-none focus:border-purple-500/50 placeholder:text-gray-600"
            />
            {url && (
              <button
                onClick={() => { setUrl(""); setResult(null); }}
                className="px-2 text-gray-500 hover:text-red-400 transition"
              >
                <X className="w-4 h-4" />
              </button>
            )}
          </div>
          <p className="text-xs text-gray-600">
            YouTube, ニコニコ動画等に対応（最大10分）
          </p>
        </div>
      )}

      {/* File Drop Zone */}
      {source === "file" && (
        <div
          onDragOver={(e) => {
            e.preventDefault();
            setDragOver(true);
          }}
          onDragLeave={() => setDragOver(false)}
          onDrop={onDrop}
          onClick={() => inputRef.current?.click()}
          className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center gap-3 cursor-pointer transition ${
            dragOver
              ? "border-purple-400 bg-purple-500/10"
              : file
              ? "border-green-500/30 bg-green-500/5"
              : "border-white/10 hover:border-white/20 hover:bg-white/5"
          }`}
        >
          <input
            ref={inputRef}
            type="file"
            accept=".mp4,.webm,.mkv,.avi,.mov"
            className="hidden"
            onChange={(e) => {
              const f = e.target.files?.[0];
              if (f) handleFile(f);
            }}
          />
          {file ? (
            <>
              <CheckCircle className="w-8 h-8 text-green-400" />
              <div className="text-sm text-green-300">{file.name}</div>
              <div className="text-xs text-gray-500">
                {(file.size / 1024 / 1024).toFixed(1)} MB
              </div>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  clear();
                }}
                className="text-xs text-gray-500 hover:text-red-400 transition flex items-center gap-1"
              >
                <X className="w-3 h-3" /> 取り消し
              </button>
            </>
          ) : (
            <>
              <Upload className="w-8 h-8 text-gray-500" />
              <div className="text-sm text-gray-400">
                ここにドラッグ&ドロップ、またはクリックして選択
              </div>
              <div className="text-xs text-gray-600">
                MP4, WebM, MKV, AVI, MOV（最大200MB）
              </div>
            </>
          )}
        </div>
      )}

      {/* Analyze Button */}
      <button
        onClick={analyze}
        disabled={!canAnalyze || loading}
        className={`flex items-center justify-center gap-2 px-4 py-3 rounded-xl text-sm font-medium transition ${
          !canAnalyze || loading
            ? "bg-white/5 text-gray-600 cursor-not-allowed"
            : "bg-purple-600/20 text-purple-300 hover:bg-purple-600/30 border border-purple-500/20"
        }`}
      >
        {loading ? (
          <>
            <Loader2 className="w-5 h-5 animate-spin" />
            {source === "url"
              ? "ダウンロード＋解析中..."
              : "解析中...（フレーム抽出＋Vision処理）"}
          </>
        ) : (
          <>
            <Play className="w-5 h-5" />
            {mode === "react" ? "リアクションを生成" : "戦略を抽出"}
          </>
        )}
      </button>

      {/* Error */}
      {error && (
        <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-sm text-red-300">
          <AlertCircle className="w-5 h-5 shrink-0" />
          {error}
        </div>
      )}

      {/* Results */}
      {result && (
        <div className="glass-panel rounded-xl p-4 space-y-3">
          <div className="flex items-center gap-2 text-sm font-medium">
            <CheckCircle className="w-5 h-5 text-green-400" />
            解析完了
            {result.frame_count != null && (
              <span className="text-xs text-gray-500 ml-auto">
                {result.frame_count} フレーム
              </span>
            )}
          </div>

          {/* Video title & duration (URL mode) */}
          {result.title && (
            <div className="text-xs text-gray-400">
              {result.title}
              {result.duration != null && result.duration > 0 && (
                <span className="ml-2 text-gray-500">
                  ({Math.floor(result.duration / 60)}:{String(result.duration % 60).padStart(2, "0")})
                </span>
              )}
            </div>
          )}

          {/* Scenes (react mode) */}
          {result.scenes && result.scenes.length > 0 && (
            <div className="space-y-2">
              <div className="text-xs text-gray-400 font-medium">
                {mode === "react" ? "場面の説明" : "検出された場面"}
              </div>
              {result.scenes.map((scene, i) => (
                <div
                  key={i}
                  className="text-sm bg-white/5 rounded-lg p-3 text-gray-300"
                >
                  <span className="text-xs text-purple-400 mr-2">#{i + 1}</span>
                  {scene}
                </div>
              ))}
            </div>
          )}

          {/* Strategies (learn mode) */}
          {result.strategies && result.strategies.length > 0 && (
            <div className="space-y-2">
              <div className="text-xs text-gray-400 font-medium">
                抽出された戦略
              </div>
              {result.strategies.map((strategy, i) => (
                <div
                  key={i}
                  className="text-sm bg-blue-500/5 border border-blue-500/10 rounded-lg p-3 text-blue-200"
                >
                  {strategy}
                </div>
              ))}
              {result.memory_ids && result.memory_ids.length > 0 && (
                <div className="text-xs text-green-400">
                  {result.memory_ids.length} 件の記憶に保存しました
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

"use client";
import React, { useRef } from 'react';
import { Send, Mic, Image as ImageIcon, StopCircle } from 'lucide-react';
import { useChatStore } from '@/lib/stores/chatStore';

interface ChatInputProps {
    onToggleListening: () => void;
    onSendMessage: () => void;
    onImageSelect: (e: React.ChangeEvent<HTMLInputElement>) => void;
    // Voice (from useVoiceMode hook — not in store)
    voiceModeEnabled: boolean;
    voiceWsState: 'idle' | 'connecting' | 'connected' | 'error';
    voiceError: string | null;
    sttPreview: string;
    onToggleVoiceMode: () => void;
}

export default function ChatInput({
    onToggleListening,
    onSendMessage,
    onImageSelect,
    voiceModeEnabled,
    voiceWsState,
    voiceError,
    sttPreview,
    onToggleVoiceMode,
}: ChatInputProps) {
    const input = useChatStore((s) => s.input);
    const setInput = useChatStore((s) => s.setInput);
    const isLoading = useChatStore((s) => s.isLoading);
    const selectedImage = useChatStore((s) => s.selectedImage);
    const setSelectedImage = useChatStore((s) => s.setSelectedImage);
    const isListening = useChatStore((s) => s.isListening);

    const fileInputRef = useRef<HTMLInputElement>(null);

    return (
        <div className="relative w-full glass p-2 rounded-2xl flex flex-col gap-2">
            {selectedImage && (
                <div className="relative w-32 h-32 bg-black/50 rounded-xl overflow-hidden group">
                    <img src={selectedImage} alt="Preview" className="w-full h-full object-cover" />
                    <button
                        onClick={() => setSelectedImage(null)}
                        className="absolute top-1 right-1 bg-red-500/80 text-white p-1 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                        <StopCircle size={14} />
                    </button>
                </div>
            )}

            <div className="flex items-center gap-1 sm:gap-2 w-full">
                <input
                    type="file"
                    ref={fileInputRef}
                    hidden
                    accept="image/*"
                    onChange={onImageSelect}
                />
                <button
                    onClick={() => fileInputRef.current?.click()}
                    className={`shrink-0 p-2 sm:p-3 rounded-xl transition-colors ${selectedImage ? 'text-blue-400 bg-blue-500/20' : 'hover:bg-white/10 text-gray-400'}`}
                >
                    <ImageIcon size={18} className="sm:hidden" />
                    <ImageIcon size={20} className="hidden sm:block" />
                </button>
                <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey && !(e.nativeEvent as any).isComposing && !isLoading) {
                            e.preventDefault();
                            onSendMessage();
                        }
                    }}
                    placeholder="メッセージを入力..."
                    className="flex-1 min-w-0 bg-transparent border-none outline-none text-white px-1 sm:px-2 placeholder-gray-500"
                    disabled={isLoading}
                />
                <button
                    onClick={onToggleVoiceMode}
                    className={`shrink-0 px-2 py-1.5 sm:px-3 sm:py-2 rounded-xl text-[10px] sm:text-xs font-medium transition-all ${voiceModeEnabled
                        ? 'bg-emerald-500 text-white shadow-[0_0_12px_rgba(16,185,129,0.45)]'
                        : 'border border-white/20 text-gray-300 hover:bg-white/10'
                        }`}
                    title={voiceModeEnabled ? "Voice Mode 停止" : "Voice Mode 開始"}
                >
                    {voiceModeEnabled ? "ON" : "VC"}
                </button>
                <button
                    onClick={onToggleListening}
                    className={`shrink-0 p-2 sm:p-3 rounded-xl transition-all ${isListening
                        ? 'bg-red-500 text-white animate-pulse shadow-[0_0_15px_rgba(239,68,68,0.5)]'
                        : 'hover:bg-white/10 text-gray-400'
                        }`}
                    title={isListening ? "音声認識停止" : "音声認識開始"}
                >
                    <Mic size={18} className="sm:hidden" />
                    <Mic size={20} className="hidden sm:block" />
                </button>
                <button
                    onClick={onSendMessage}
                    disabled={isLoading || (!input.trim() && !selectedImage)}
                    className="shrink-0 p-2 sm:p-3 rounded-xl bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-600/20 disabled:opacity-50 transition-all active:scale-95"
                >
                    <Send size={18} className="sm:hidden" />
                    <Send size={20} className="hidden sm:block" />
                </button>
            </div>
            {(voiceModeEnabled || voiceWsState !== "idle" || voiceError) && (
                <div className="px-2 text-[11px] text-gray-400">
                    <span>voice_ws: {voiceWsState}</span>
                    {sttPreview && <span className="ml-2 text-emerald-300">stt: {sttPreview}</span>}
                    {voiceError && <span className="ml-2 text-red-300">{voiceError}</span>}
                </div>
            )}
        </div>
    );
}

"use client";
import React, { useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useChatStore } from '@/lib/stores/chatStore';

export default function ChatMessages() {
    const messages = useChatStore((s) => s.messages);
    const isLoading = useChatStore((s) => s.isLoading);
    const scrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [messages]);

    return (
        <div className="flex-1 overflow-y-auto overflow-x-hidden mb-4 space-y-4 px-2" ref={scrollRef}>
